/**
 * App - Main Application Class
 *
 * Responsibilities:
 * - Initialize all controllers and services
 * - Coordinate between components
 * - Setup event listeners
 * - Handle application lifecycle
 * - Manage keyboard shortcuts
 * - Initialize auto-save
 */

import { AppStore, initStore } from './store/AppStore';
import { TimerController } from './controllers/TimerController';
import { UIController } from './controllers/UIController';
import { KeyboardShortcutManager, DefaultShortcuts } from './services/keyboard';
import { AutoSaveManager } from './services/autoSave';
import { createStorageService } from './services/storage';
import { IStorageService } from './types/index';

/**
 * Application configuration
 */
export interface AppConfig {
  // Storage
  storageType?: 'local' | 'memory';

  // Auto-save
  autoSave?: boolean;
  autoSaveDebounceMs?: number;

  // Keyboard shortcuts
  enableKeyboardShortcuts?: boolean;

  // Notifications
  enableNotifications?: boolean;

  // Debug mode
  debug?: boolean;

  // Initial state
  initialState?: any;
}

/**
 * App - Main application class
 */
export class App {
  // Core services
  private store: AppStore;
  private storage: IStorageService;

  // Controllers
  private timerController: TimerController | null = null;
  private uiController: UIController | null = null;
  private keyboardManager: KeyboardShortcutManager | null = null;

  // Managers
  private autoSaveManager: AutoSaveManager | null = null;

  // State
  private initialized: boolean = false;
  private destroyed: boolean = false;
  private config: Required<AppConfig>;

  // Cleanup functions
  private cleanupFunctions: Array<() => void> = [];

  /**
   * Constructor
   */
  constructor(config: AppConfig = {}) {
    // Merge config with defaults
    this.config = {
      storageType: config.storageType ?? 'local',
      autoSave: config.autoSave ?? true,
      autoSaveDebounceMs: config.autoSaveDebounceMs ?? 2000,
      enableKeyboardShortcuts: config.enableKeyboardShortcuts ?? true,
      enableNotifications: config.enableNotifications ?? true,
      debug: config.debug ?? false,
      initialState: config.initialState,
    };

    // Initialize storage
    this.storage = createStorageService(this.config.storageType);

    // Initialize store
    this.store = initStore(this.config.initialState);

    this.log('App created');
  }

  // ==========================================================================
  // INITIALIZATION
  // ==========================================================================

  /**
   * Initialize the application
   */
  async initialize(): Promise<void> {
    if (this.initialized) {
      this.log('App already initialized');
      return;
    }

    if (this.destroyed) {
      throw new Error('Cannot initialize destroyed app');
    }

    this.log('Initializing app...');

    try {
      // Set loading state
      this.store.setLoading(true);

      // Step 1: Load saved data
      await this.loadSavedData();

      // Step 2: Initialize controllers
      this.initializeControllers();

      // Step 3: Setup keyboard shortcuts
      if (this.config.enableKeyboardShortcuts) {
        this.setupKeyboardShortcuts();
      }

      // Step 4: Setup event listeners
      this.setupEventListeners();

      // Step 5: Initialize auto-save
      if (this.config.autoSave) {
        this.initializeAutoSave();
      }

      // Step 6: Setup theme
      this.initializeTheme();

      // Clear loading state
      this.store.setLoading(false);

      this.initialized = true;
      this.log('App initialized successfully');
    } catch (error) {
      this.store.setLoading(false);
      this.store.setError(`Initialization failed: ${error}`);
      console.error('Failed to initialize app:', error);
      throw error;
    }
  }

  /**
   * Load saved data from storage
   */
  private async loadSavedData(): Promise<void> {
    this.log('Loading saved data...');

    try {
      // Load tasks
      const tasks = await this.storage.getTasks();
      this.log(`Loaded ${tasks.length} tasks`);

      // Load sessions
      const sessions = await this.storage.getSessions();
      this.log(`Loaded ${sessions.length} sessions`);

      // Load settings
      const settings = await this.storage.getSettings();
      this.log('Loaded settings');

      // Load stats
      const today = new Date().toISOString().split('T')[0];
      const todayStats = await this.storage.getDailyStats(today);
      if (todayStats) {
        this.log("Loaded today's statistics");
      }

      // Update store with loaded data
      // Note: In a real app, you would merge this with initial state
      // and handle migrations if needed
    } catch (error) {
      this.log('Failed to load saved data', error);
      // Don't throw - allow app to start with empty state
    }
  }

  /**
   * Initialize controllers
   */
  private initializeControllers(): void {
    this.log('Initializing controllers...');

    // Initialize TimerController
    this.timerController = new TimerController({
      store: this.store,
      onTick: (remainingTime) => {
        // UI will update via store subscription
        this.debugLog(`Timer tick: ${remainingTime}s remaining`);
      },
      onSessionComplete: (sessionType) => {
        this.log(`Session completed: ${sessionType}`);
        // UI will show notification via timer events
      },
      notificationEnabled: this.config.enableNotifications,
      soundEnabled: true,
    });

    // Initialize UIController
    this.uiController = new UIController({
      store: this.store,
      autoBind: true,
      enableAnimations: true,
    });

    this.log('Controllers initialized');
  }

  /**
   * Setup keyboard shortcuts
   */
  private setupKeyboardShortcuts(): void {
    this.log('Setting up keyboard shortcuts...');

    this.keyboardManager = new KeyboardShortcutManager();

    // Register default shortcuts
    DefaultShortcuts.register(this.keyboardManager, {
      startPauseTimer: () => this.handleStartPauseTimer(),
      newTask: () => this.handleNewTask(),
      completeTask: () => this.handleCompleteTask(),
      nextTask: () => this.handleNextTask(),
      previousTask: () => this.handlePreviousTask(),
      openSettings: () => this.handleOpenSettings(),
      resetTimer: () => this.handleResetTimer(),
      skipSession: () => this.handleSkipSession(),
      toggleTimer: () => this.handleToggleTimer(),
      deleteTask: () => this.handleDeleteTask(),
      editTask: () => this.handleEditTask(),
      focusSearch: () => this.handleFocusSearch(),
      toggleSidebar: () => this.handleToggleSidebar(),
    });

    this.log('Keyboard shortcuts registered');
  }

  /**
   * Setup event listeners
   */
  private setupEventListeners(): void {
    this.log('Setting up event listeners...');

    // Timer events
    window.addEventListener('timer:start', () => {
      this.timerController?.start();
    });

    window.addEventListener('timer:pause', () => {
      this.timerController?.pause();
    });

    window.addEventListener('timer:reset', () => {
      this.timerController?.reset();
    });

    window.addEventListener('timer:skip', () => {
      this.timerController?.skip();
    });

    // Task events
    window.addEventListener('task:activate', (e: any) => {
      const taskId = e.detail?.taskId;
      if (taskId) {
        this.store.setActiveTask(taskId);
      }
    });

    window.addEventListener('task:complete', (e: any) => {
      const taskId = e.detail?.taskId;
      if (taskId) {
        this.store.completeTask(taskId);
      }
    });

    window.addEventListener('task:delete', (e: any) => {
      const taskId = e.detail?.taskId;
      if (taskId) {
        this.store.deleteTask(taskId);
      }
    });

    // Window visibility change
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        this.log('App hidden');
      } else {
        this.log('App visible');
      }
    });

    // Window before unload
    window.addEventListener('beforeunload', () => {
      this.log('App before unload');
      this.cleanup();
    });

    this.log('Event listeners setup complete');
  }

  /**
   * Initialize auto-save
   */
  private initializeAutoSave(): void {
    this.log('Initializing auto-save...');

    this.autoSaveManager = new AutoSaveManager(this.store, {
      enabled: true,
      debounceMs: this.config.autoSaveDebounceMs,
      onSave: () => {
        this.debugLog('Auto-save completed');
      },
      onError: (error) => {
        console.error('Auto-save failed:', error);
      },
    });

    this.autoSaveManager.start();

    this.log('Auto-save initialized');
  }

  /**
   * Initialize theme
   */
  private initializeTheme(): void {
    this.log('Initializing theme...');

    const savedTheme = localStorage.getItem('theme') as 'light' | 'dark' | null;

    if (savedTheme) {
      this.uiController?.setTheme(savedTheme);
    } else {
      // Detect system preference
      const prefersDark = window.matchMedia(
        '(prefers-color-scheme: dark)'
      ).matches;
      this.uiController?.setTheme(prefersDark ? 'dark' : 'light');
    }

    // Listen for system theme changes
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handleThemeChange = (e: MediaQueryListEvent) => {
      if (!localStorage.getItem('theme')) {
        this.uiController?.setTheme(e.matches ? 'dark' : 'light');
      }
    };

    mediaQuery.addEventListener('change', handleThemeChange);

    this.cleanupFunctions.push(() => {
      mediaQuery.removeEventListener('change', handleThemeChange);
    });
  }

  // ==========================================================================
  // KEYBOARD SHORTCUT HANDLERS
  // ==========================================================================

  private async handleStartPauseTimer(): Promise<void> {
    const state = this.store.getTimerState();
    if (state === 'idle' || state === 'paused') {
      await this.timerController?.start();
    } else {
      await this.timerController?.pause();
    }
  }

  private handleToggleTimer(): void {
    this.timerController?.toggle();
  }

  private handleResetTimer(): void {
    this.timerController?.reset();
  }

  private handleSkipSession(): void {
    this.timerController?.skip();
  }

  private handleNewTask(): void {
    this.uiController?.showAddTaskModal();
  }

  private async handleCompleteTask(): Promise<void> {
    const activeTask = this.store.getActiveTask();
    if (activeTask) {
      await this.store.completeTask(activeTask.id);
      this.uiController?.showToast('Task completed!', 'success');
    } else {
      this.uiController?.showToast('No active task', 'info');
    }
  }

  private async handleNextTask(): Promise<void> {
    const tasks = this.store.getTasks();
    const activeTask = this.store.getActiveTask();

    if (tasks.length === 0) return;

    const currentIndex = activeTask
      ? tasks.findIndex((t) => t.id === activeTask.id)
      : -1;

    const nextIndex = (currentIndex + 1) % tasks.length;
    await this.store.setActiveTask(tasks[nextIndex].id);
    this.uiController?.showToast(
      `Activated: ${tasks[nextIndex].title}`,
      'info'
    );
  }

  private async handlePreviousTask(): Promise<void> {
    const tasks = this.store.getTasks();
    const activeTask = this.store.getActiveTask();

    if (tasks.length === 0) return;

    const currentIndex = activeTask
      ? tasks.findIndex((t) => t.id === activeTask.id)
      : 0;

    const prevIndex = currentIndex <= 0 ? tasks.length - 1 : currentIndex - 1;
    await this.store.setActiveTask(tasks[prevIndex].id);
    this.uiController?.showToast(
      `Activated: ${tasks[prevIndex].title}`,
      'info'
    );
  }

  private handleDeleteTask(): void {
    const activeTask = this.store.getActiveTask();
    if (activeTask) {
      this.store.deleteTask(activeTask.id);
      this.uiController?.showToast('Task deleted', 'info');
    }
  }

  private handleEditTask(): void {
    const activeTask = this.store.getActiveTask();
    if (activeTask) {
      this.uiController?.showEditTaskModal(activeTask);
    }
  }

  private handleOpenSettings(): void {
    this.uiController?.showModal(document.getElementById('settings-modal')!);
  }

  private handleFocusSearch(): void {
    const searchInput = document.getElementById(
      'search-input'
    ) as HTMLInputElement;
    if (searchInput) {
      searchInput.focus();
    }
  }

  private handleToggleSidebar(): void {
    const sidebar = document.getElementById('sidebar');
    if (sidebar) {
      sidebar.classList.toggle('collapsed');
    }
  }

  // ==========================================================================
  // PUBLIC API
  // ==========================================================================

  /**
   * Get the store instance
   */
  getStore(): AppStore {
    return this.store;
  }

  /**
   * Get the timer controller
   */
  getTimerController(): TimerController | null {
    return this.timerController;
  }

  /**
   * Get the UI controller
   */
  getUIController(): UIController | null {
    return this.uiController;
  }

  /**
   * Get the keyboard manager
   */
  getKeyboardManager(): KeyboardShortcutManager | null {
    return this.keyboardManager;
  }

  /**
   * Check if app is initialized
   */
  isInitialized(): boolean {
    return this.initialized;
  }

  /**
   * Get app configuration
   */
  getConfig(): Readonly<Required<AppConfig>> {
    return this.config;
  }

  // ==========================================================================
  // CLEANUP
  // ==========================================================================

  /**
   * Cleanup resources
   */
  private cleanup(): void {
    this.log('Cleaning up...');

    // Stop auto-save
    if (this.autoSaveManager) {
      this.autoSaveManager.stop();
      this.autoSaveManager.destroy();
      this.autoSaveManager = null;
    }

    // Destroy timer controller
    if (this.timerController) {
      this.timerController.destroy();
      this.timerController = null;
    }

    // Destroy UI controller
    if (this.uiController) {
      this.uiController.destroy();
      this.uiController = null;
    }

    // Destroy keyboard manager
    if (this.keyboardManager) {
      this.keyboardManager.destroy();
      this.keyboardManager = null;
    }

    // Run cleanup functions
    this.cleanupFunctions.forEach((fn) => {
      try {
        fn();
      } catch (error) {
        console.error('Error in cleanup function:', error);
      }
    });
    this.cleanupFunctions = [];

    this.log('Cleanup complete');
  }

  /**
   * Destroy the app
   */
  destroy(): void {
    if (this.destroyed) {
      return;
    }

    this.log('Destroying app...');
    this.cleanup();
    this.destroyed = true;
    this.log('App destroyed');
  }

  // ==========================================================================
  // LOGGING
  // ==========================================================================

  private log(message: string, error?: any): void {
    if (this.config.debug) {
      console.log(`[App] ${message}`, error ?? '');
    }
  }

  private debugLog(message: string): void {
    if (this.config.debug) {
      console.debug(`[App] ${message}`);
    }
  }
}

// ============================================================================
// EXPORTS
// ============================================================================

export default App;

/**
 * Create and initialize an app instance
 */
export async function createApp(config?: AppConfig): Promise<App> {
  const app = new App(config);
  await app.initialize();
  return app;
}

/**
 * Get the singleton app instance
 */
let appInstance: App | null = null;

export function getApp(): App {
  if (!appInstance) {
    throw new Error('App not initialized. Call createApp() first.');
  }
  return appInstance;
}

export function setApp(app: App): void {
  appInstance = app;
}

export function destroyApp(): void {
  if (appInstance) {
    appInstance.destroy();
    appInstance = null;
  }
}

/**
 * 番茄钟计时器核心逻辑
 */

import { TimerInfo, TimerMode, TimerState, AppSettings } from '../types';
import { eventEmitter } from '../utils/EventEmitter';
import { toastManager } from '../utils/ToastManager';
import { Component } from '../core/Component';

export class PomodoroTimer extends Component {
  private mode: TimerMode = 'pomodoro';
  private state: TimerState = 'idle';
  private timeRemaining: number = 25 * 60; // 秒
  private totalTime: number = 25 * 60; // 秒
  private completedPomodoros: number = 0;
  private intervalId: number | null = null;
  private currentTaskId: string | null = null;
  private settings: AppSettings;

  constructor(settings: AppSettings) {
    super();
    this.settings = settings;
    this.initializeEventListeners();
    this.updateTimerConfig();

    // Register cleanup
    this.addAutoCleanup(() => {
      this.settings = null as any;
      this.currentTaskId = null;
    });
  }

  /**
   * 初始化事件监听器
   */
  private initializeEventListeners(): void {
    // 开始/暂停按钮
    const toggleBtn = document.getElementById('timer-toggle-btn');
    toggleBtn && this.addEventListener(toggleBtn, 'click', () => this.toggle());

    // 重置按钮
    const resetBtn = document.getElementById('timer-reset-btn');
    resetBtn && this.addEventListener(resetBtn, 'click', () => this.reset());

    // 跳过按钮
    const skipBtn = document.getElementById('timer-skip-btn');
    skipBtn && this.addEventListener(skipBtn, 'click', () => this.skip());

    // 监听设置更新 - 使用 subscribeEvent 自动跟踪
    this.subscribeEvent('settings:update', (settings: AppSettings) => {
      this.settings = settings;
      this.updateTimerConfig();
    });

    // 监听任务激活
    this.subscribeEvent('task:activated', (task: any) => {
      this.currentTaskId = task.id;
    });

    // 监听模式切换
    this.subscribeEvent('timer:modeChange', (mode: TimerMode) => {
      this.setMode(mode);
    });

    // 键盘快捷键
    this.addEventListener(document, 'keydown', (e) => {
      // 空格键开始/暂停（仅在未聚焦输入框时）
      if (
        e.code === 'Space' &&
        document.activeElement?.tagName !== 'INPUT' &&
        document.activeElement?.tagName !== 'TEXTAREA'
      ) {
        e.preventDefault();
        this.toggle();
      }

      // Alt+R 重置
      if (e.altKey && e.key === 'r') {
        e.preventDefault();
        this.reset();
      }

      // Alt+1/2/3 切换模式
      if (e.altKey && e.key === '1') {
        e.preventDefault();
        eventEmitter.emit('timer:modeChange', 'pomodoro');
      }
      if (e.altKey && e.key === '2') {
        e.preventDefault();
        eventEmitter.emit('timer:modeChange', 'shortBreak');
      }
      if (e.altKey && e.key === '3') {
        e.preventDefault();
        eventEmitter.emit('timer:modeChange', 'longBreak');
      }
    });
  }

  /**
   * 更新计时器配置
   */
  private updateTimerConfig(): void {
    if (this.state === 'idle') {
      this.setMode(this.mode);
    }
  }

  /**
   * 切换开始/暂停
   */
  public toggle(): void {
    if (this.state === 'running') {
      this.pause();
    } else {
      this.start();
    }
  }

  /**
   * 开始计时
   */
  public start(): void {
    if (this.state === 'running') return;

    this.state = 'running';
    eventEmitter.emit('timer:start');

    this.intervalId = this.setInterval(() => {
      this.tick();
    }, 1000);

    toastManager.info(
      this.getModeLabel(),
      `开始 ${this.getModeLabel()} - ${this.formatTime(this.timeRemaining)}`
    );
  }

  /**
   * 暂停计时
   */
  public pause(): void {
    if (this.state !== 'running') return;

    this.state = 'paused';
    eventEmitter.emit('timer:pause');

    if (this.intervalId !== null) {
      this.clearInterval(this.intervalId);
      this.intervalId = null;
    }

    toastManager.info(
      '计时已暂停',
      `剩余时间：${this.formatTime(this.timeRemaining)}`
    );
  }

  /**
   * 重置计时
   */
  public reset(): void {
    if (this.state === 'running') {
      this.pause();
    }

    this.timeRemaining = this.totalTime;
    this.state = 'idle';
    eventEmitter.emit('timer:reset');
    eventEmitter.emit('timer:update', this.getInfo());

    toastManager.info(
      '计时已重置',
      `计时器已重置为 ${this.formatTime(this.timeRemaining)}`
    );
  }

  /**
   * 跳过当前时段
   */
  public skip(): void {
    this.complete();
  }

  /**
   * 计时器滴答
   */
  private tick(): void {
    this.timeRemaining--;

    eventEmitter.emit('timer:update', this.getInfo());

    if (this.timeRemaining <= 0) {
      this.complete();
    }
  }

  /**
   * 完成当前时段
   */
  private complete(): void {
    if (this.intervalId !== null) {
      this.clearInterval(this.intervalId);
      this.intervalId = null;
    }

    this.state = 'completed';
    eventEmitter.emit('timer:complete');

    // 如果是番茄钟，增加计数
    if (this.mode === 'pomodoro') {
      this.completedPomodoros++;
      this.saveCompletedPomodoro();

      // 通知统计面板
      eventEmitter.emit('pomodoro:completed', {
        count: this.completedPomodoros,
        taskId: this.currentTaskId,
      });

      toastManager.success(
        '番茄钟完成！',
        `已完成 ${this.completedPomodoros} 个番茄钟，休息一下吧！`
      );

      // 切换到休息模式
      if (
        this.completedPomodoros % this.settings.timer.longBreakInterval ===
        0
      ) {
        this.setMode('longBreak');
      } else {
        this.setMode('shortBreak');
      }

      // 自动开始休息（如果设置启用）
      if (this.settings.notifications.autoStartBreaks) {
        this.setTimeout(() => this.start(), 1000);
      }
    } else {
      // 休息完成，切换回番茄钟
      toastManager.success('休息结束！', '准备好开始新的专注了吗？');
      this.setMode('pomodoro');

      // 自动开始番茄钟（如果设置启用）
      if (this.settings.notifications.autoStartPomodoros) {
        this.setTimeout(() => this.start(), 1000);
      }
    }
  }

  /**
   * 设置模式
   */
  public setMode(mode: TimerMode): void {
    // 如果正在运行，先暂停
    if (this.state === 'running') {
      this.pause();
    }

    this.mode = mode;

    // 设置时长
    switch (mode) {
      case 'pomodoro':
        this.totalTime = this.settings.timer.pomodoroDuration;
        break;
      case 'shortBreak':
        this.totalTime = this.settings.timer.shortBreakDuration;
        break;
      case 'longBreak':
        this.totalTime = this.settings.timer.longBreakDuration;
        break;
    }

    this.timeRemaining = this.totalTime;
    this.state = 'idle';

    eventEmitter.emit('timer:modeChange', mode);
    eventEmitter.emit('timer:update', this.getInfo());
  }

  /**
   * 保存完成的番茄钟
   */
  private saveCompletedPomodoro(): void {
    const today = new Date();
    const dateKey = this.formatDateKey(today);

    const currentCount = parseInt(
      localStorage.getItem(`pomodoros_${dateKey}`) || '0',
      10
    );
    localStorage.setItem(`pomodoros_${dateKey}`, (currentCount + 1).toString());
  }

  /**
   * 格式化日期键
   */
  private formatDateKey(date: Date): string {
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  }

  /**
   * 格式化时间
   */
  private formatTime(seconds: number): string {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  /**
   * 获取模式标签
   */
  private getModeLabel(): string {
    const labels: Record<TimerMode, string> = {
      pomodoro: '番茄钟',
      shortBreak: '短休息',
      longBreak: '长休息',
    };
    return labels[this.mode];
  }

  /**
   * 获取计时器信息
   */
  public getInfo(): TimerInfo {
    return {
      mode: this.mode,
      state: this.state,
      timeRemaining: this.timeRemaining,
      totalTime: this.totalTime,
      completedPomodoros: this.completedPomodoros,
      currentTaskId: this.currentTaskId || undefined,
    };
  }

  /**
   * 获取当前模式
   */
  public getMode(): TimerMode {
    return this.mode;
  }

  /**
   * 获取当前状态
   */
  public getState(): TimerState {
    return this.state;
  }

  /**
   * 销毁计时器 (override from Component)
   */
  public destroy(): void {
    if (this.intervalId !== null) {
      this.clearInterval(this.intervalId);
      this.intervalId = null;
    }
    super.destroy();
  }
}

/**
 * 设置对话框组件
 */

import { AppSettings, SettingsFormData } from '../types';
import { eventEmitter } from '../utils/EventEmitter';
import { toastManager } from '../utils/ToastManager';

export class SettingsModal {
  private modal: HTMLElement;
  private form: HTMLElement;
  private settings: AppSettings;

  constructor() {
    this.modal = document.getElementById('settings-modal')!;
    this.form = this.modal.querySelector('.modal-body')!;
    this.settings = this.loadSettings();

    this.initializeEventListeners();
    this.populateForm();
  }

  /**
   * 初始化事件监听器
   */
  private initializeEventListeners(): void {
    // 打开设置按钮
    const settingsBtn = document.getElementById('settings-btn');
    settingsBtn?.addEventListener('click', () => this.show());

    // 关闭按钮
    const closeButtons = this.modal.querySelectorAll(
      '[data-modal-close], [data-modal-cancel]'
    );
    closeButtons.forEach((btn) => {
      btn.addEventListener('click', () => this.hide());
    });

    // 保存按钮
    const saveBtn = this.modal.querySelector(
      '[data-modal-confirm]'
    ) as HTMLElement;
    saveBtn?.addEventListener('click', () => this.save());

    // 点击遮罩层关闭
    const overlay = this.modal.querySelector('[data-modal-overlay]');
    overlay?.addEventListener('click', () => this.hide());

    // ESC 键关闭
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.isShown()) {
        this.hide();
      }
    });
  }

  /**
   * 显示设置对话框
   */
  public show(): void {
    this.populateForm();
    this.modal.setAttribute('aria-hidden', 'false');
    this.modal.style.display = 'flex';
    document.body.style.overflow = 'hidden';
  }

  /**
   * 隐藏设置对话框
   */
  public hide(): void {
    this.modal.setAttribute('aria-hidden', 'true');
    this.modal.style.display = 'none';
    document.body.style.overflow = '';
  }

  /**
   * 检查是否显示
   */
  public isShown(): boolean {
    return this.modal.getAttribute('aria-hidden') === 'false';
  }

  /**
   * 填充表单
   */
  private populateForm(): void {
    const elements = {
      pomodoroDuration: document.getElementById(
        'pomodoro-duration'
      ) as HTMLInputElement,
      shortBreakDuration: document.getElementById(
        'short-break-duration'
      ) as HTMLInputElement,
      longBreakDuration: document.getElementById(
        'long-break-duration'
      ) as HTMLInputElement,
      longBreakInterval: document.getElementById(
        'long-break-interval'
      ) as HTMLInputElement,
      dailyGoal: document.getElementById('daily-goal') as HTMLInputElement,
      enableNotifications: document.getElementById(
        'enable-notifications'
      ) as HTMLInputElement,
      enableSound: document.getElementById('enable-sound') as HTMLInputElement,
      autoStartBreaks: document.getElementById(
        'auto-start-breaks'
      ) as HTMLInputElement,
      autoStartPomodoros: document.getElementById(
        'auto-start-pomodoros'
      ) as HTMLInputElement,
      themeSelect: document.getElementById('theme-select') as HTMLSelectElement,
    };

    elements.pomodoroDuration.value = (
      this.settings.timer.pomodoroDuration / 60
    ).toString();
    elements.shortBreakDuration.value = (
      this.settings.timer.shortBreakDuration / 60
    ).toString();
    elements.longBreakDuration.value = (
      this.settings.timer.longBreakDuration / 60
    ).toString();
    elements.longBreakInterval.value =
      this.settings.timer.longBreakInterval.toString();
    elements.dailyGoal.value = this.settings.dailyGoal.toString();
    elements.enableNotifications.checked = this.settings.notifications.enabled;
    elements.enableSound.checked = this.settings.notifications.sound;
    elements.autoStartBreaks.checked =
      this.settings.notifications.autoStartBreaks;
    elements.autoStartPomodoros.checked =
      this.settings.notifications.autoStartPomodoros;
    elements.themeSelect.value = this.settings.appearance.theme;
  }

  /**
   * 保存设置
   */
  public save(): void {
    const elements = {
      pomodoroDuration: document.getElementById(
        'pomodoro-duration'
      ) as HTMLInputElement,
      shortBreakDuration: document.getElementById(
        'short-break-duration'
      ) as HTMLInputElement,
      longBreakDuration: document.getElementById(
        'long-break-duration'
      ) as HTMLInputElement,
      longBreakInterval: document.getElementById(
        'long-break-interval'
      ) as HTMLInputElement,
      dailyGoal: document.getElementById('daily-goal') as HTMLInputElement,
      enableNotifications: document.getElementById(
        'enable-notifications'
      ) as HTMLInputElement,
      enableSound: document.getElementById('enable-sound') as HTMLInputElement,
      autoStartBreaks: document.getElementById(
        'auto-start-breaks'
      ) as HTMLInputElement,
      autoStartPomodoros: document.getElementById(
        'auto-start-pomodoros'
      ) as HTMLInputElement,
      themeSelect: document.getElementById('theme-select') as HTMLSelectElement,
    };

    const formData: SettingsFormData = {
      pomodoroDuration: parseInt(elements.pomodoroDuration.value, 10) * 60,
      shortBreakDuration: parseInt(elements.shortBreakDuration.value, 10) * 60,
      longBreakDuration: parseInt(elements.longBreakDuration.value, 10) * 60,
      longBreakInterval: parseInt(elements.longBreakInterval.value, 10),
      dailyGoal: parseInt(elements.dailyGoal.value, 10),
      enableNotifications: elements.enableNotifications.checked,
      enableSound: elements.enableSound.checked,
      autoStartBreaks: elements.autoStartBreaks.checked,
      autoStartPomodoros: elements.autoStartPomodoros.checked,
      theme: elements.themeSelect.value as 'light' | 'dark' | 'auto',
    };

    if (!this.validate(formData)) {
      return;
    }

    // 更新设置
    this.settings = {
      timer: {
        pomodoroDuration: formData.pomodoroDuration,
        shortBreakDuration: formData.shortBreakDuration,
        longBreakDuration: formData.longBreakDuration,
        longBreakInterval: formData.longBreakInterval,
      },
      notifications: {
        enabled: formData.enableNotifications,
        sound: formData.enableSound,
        autoStartBreaks: formData.autoStartBreaks,
        autoStartPomodoros: formData.autoStartPomodoros,
      },
      appearance: {
        theme: formData.theme,
      },
      dailyGoal: formData.dailyGoal,
    };

    // 保存到本地存储
    this.saveToStorage();

    // 应用主题
    this.applyTheme();

    // 触发设置更新事件
    eventEmitter.emit('settings:update', this.settings);

    toastManager.success('设置已保存', '您的设置已成功保存');

    this.hide();
  }

  /**
   * 验证设置
   */
  private validate(data: SettingsFormData): boolean {
    // 验证时长范围
    if (data.pomodoroDuration < 60 || data.pomodoroDuration > 3600) {
      toastManager.error('验证失败', '专注时长必须在 1-60 分钟之间');
      return false;
    }

    if (data.shortBreakDuration < 60 || data.shortBreakDuration > 1800) {
      toastManager.error('验证失败', '短休息时长必须在 1-30 分钟之间');
      return false;
    }

    if (data.longBreakDuration < 60 || data.longBreakDuration > 3600) {
      toastManager.error('验证失败', '长休息时长必须在 1-60 分钟之间');
      return false;
    }

    if (data.longBreakInterval < 2 || data.longBreakInterval > 10) {
      toastManager.error('验证失败', '长休息间隔必须在 2-10 之间');
      return false;
    }

    if (data.dailyGoal < 1 || data.dailyGoal > 20) {
      toastManager.error('验证失败', '每日目标必须在 1-20 之间');
      return false;
    }

    return true;
  }

  /**
   * 加载设置
   */
  private loadSettings(): AppSettings {
    const stored = localStorage.getItem('app_settings');
    if (stored) {
      try {
        return JSON.parse(stored);
      } catch (error) {
        console.error('Error loading settings:', error);
      }
    }

    // 返回默认设置
    return {
      timer: {
        pomodoroDuration: 25 * 60,
        shortBreakDuration: 5 * 60,
        longBreakDuration: 15 * 60,
        longBreakInterval: 4,
      },
      notifications: {
        enabled: true,
        sound: true,
        autoStartBreaks: false,
        autoStartPomodoros: false,
      },
      appearance: {
        theme: 'light',
      },
      dailyGoal: 8,
    };
  }

  /**
   * 保存到本地存储
   */
  private saveToStorage(): void {
    localStorage.setItem('app_settings', JSON.stringify(this.settings));
  }

  /**
   * 应用主题
   */
  private applyTheme(): void {
    const theme = this.settings.appearance.theme;

    if (theme === 'auto') {
      // 检测系统主题
      const prefersDark = window.matchMedia(
        '(prefers-color-scheme: dark)'
      ).matches;
      document.documentElement.setAttribute(
        'data-theme',
        prefersDark ? 'dark' : 'light'
      );

      // 监听系统主题变化
      window
        .matchMedia('(prefers-color-scheme: dark)')
        .addEventListener('change', (e) => {
          if (this.settings.appearance.theme === 'auto') {
            document.documentElement.setAttribute(
              'data-theme',
              e.matches ? 'dark' : 'light'
            );
          }
        });
    } else {
      document.documentElement.setAttribute('data-theme', theme);
    }
  }

  /**
   * 获取当前设置
   */
  public getSettings(): AppSettings {
    return this.settings;
  }

  /**
   * 更新设置
   */
  public updateSettings(settings: Partial<AppSettings>): void {
    this.settings = { ...this.settings, ...settings };
    this.saveToStorage();
    this.applyTheme();
  }
}

/**
 * 统计面板组件
