  private initializeEventListeners(): void {
    // 监听过滤器变化
    const filterButtons = document.querySelectorAll('.filter-btn');
    filterButtons.forEach((btn) => {
      this.addEventListener(btn, 'click', () => {
        const filter = btn.getAttribute('data-filter') as TaskFilter;
        this.setFilter(filter);
      });
    });

    // 监听任务事件 - 使用 subscribeEvent 自动跟踪
    this.subscribeEvent('task:add', (task: Task) => this.addTask(task));
    this.subscribeEvent('task:update', (task: Task) => this.updateTask(task));
    this.subscribeEvent('task:delete', (id: string) => this.deleteTask(id));
    this.subscribeEvent('task:complete', (id: string) =>
      this.toggleTaskComplete(id)
    );
    this.subscribeEvent('task:activate', (id: string) =>
      this.setActiveTask(id)
    );
  }

  /**
   * 设置过滤器
   */
  private setFilter(filter: TaskFilter): void {
    this.currentFilter = filter;

    // 更新按钮状态
    const filterButtons = document.querySelectorAll('.filter-btn');
    filterButtons.forEach((btn) => {
      const btnFilter = btn.getAttribute('data-filter');
      const isActive = btnFilter === filter;
      btn.classList.toggle('filter-btn-active', isActive);
      btn.setAttribute('aria-pressed', isActive.toString());
    });

    this.render();
  }

  /**
   * 渲染任务列表
   */
  public render(): void {
    const filteredTasks = this.getFilteredTasks();
    this.updateCounts();

    if (filteredTasks.length === 0) {
      this.renderEmptyState();
      return;
    }

    this.container.innerHTML = '';
    filteredTasks.forEach((task) => {
      const taskElement = this.renderTask(task);
      this.container.appendChild(taskElement);
    });
  }

  /**
   * 获取过滤后的任务
   */
  private getFilteredTasks(): Task[] {
    switch (this.currentFilter) {
      case 'active':
        return this.tasks.filter((task) => task.status === 'active');
      case 'completed':
        return this.tasks.filter((task) => task.status === 'completed');
      default:
        return this.tasks;
    }
  }

  /**
   * 渲染空状态
   */
  private renderEmptyState(): void {
    const messages: Record<
      TaskFilter,
      { icon: string; text: string; hint: string }
    > = {
      all: { icon: '📝', text: '还没有任务', hint: '点击"添加任务"开始使用' },
      active: {
        icon: '🎯',
        text: '没有进行中的任务',
        hint: '添加新任务或从已完成任务中选择',
      },
      completed: {
        icon: '✅',
        text: '还没有完成任何任务',
        hint: '完成任务后会显示在这里',
      },
    };

    const message = messages[this.currentFilter];

    this.container.innerHTML = `
            <div class="empty-state">
                <div class="empty-icon" aria-hidden="true">${message.icon}</div>
                <p>${message.text}</p>
                <p class="empty-hint">${message.hint}</p>
            </div>
        `;
  }

  /**
   * 渲染单个任务
   */
  private renderTask(task: Task): HTMLElement {
    const taskElement = document.createElement('div');
    taskElement.className = 'task-item';
    taskElement.setAttribute('role', 'listitem');
    taskElement.dataset.taskId = task.id;

    const isActive = this.activeTaskId === task.id;
    const isCompleted = task.status === 'completed';

    taskElement.classList.toggle('active-task', isActive);
    taskElement.classList.toggle('completed', isCompleted);

    const priorityClass = `task-priority-${task.priority}`;
    const progressPercent =
      (task.completedPomodoros / task.estimatedPomodoros) * 100;

    taskElement.innerHTML = `
            <label class="task-checkbox">
                <input
                    type="checkbox"
                    ${isCompleted ? 'checked' : ''}
                    aria-label="标记任务为完成">
                <span class="task-checkbox-custom"></span>
            </label>

            <div class="task-content">
                <h3 class="task-title">${this.escapeHtml(task.title)}</h3>
                ${task.description ? `<p class="task-description">${this.escapeHtml(task.description)}</p>` : ''}

                <div class="task-meta">
                    <span class="task-priority ${priorityClass}">
                        ${this.getPriorityLabel(task.priority)}
                    </span>
                    <span class="task-pomodoros">
                        <span class="task-pomodoros-icon">🍅</span>
                        <span class="task-pomodoros-count ${task.completedPomodoros > 0 ? 'completed' : ''}">
                            ${task.completedPomodoros}
                        </span>
                        / ${task.estimatedPomodoros}
                    </span>
                </div>
            </div>

            <div class="task-actions">
                <button
                    class="task-action-btn play"
                    aria-label="开始专注此任务"
                    title="开始专注">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <polygon points="5 3 19 12 5 21 5 3"></polygon>
                    </svg>
                </button>
                <button
                    class="task-action-btn edit"
                    aria-label="编辑任务"
                    title="编辑">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
                        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
                    </svg>
                </button>
                <button
                    class="task-action-btn delete"
                    aria-label="删除任务"
                    title="删除">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <polyline points="3 6 5 6 21 6"></polyline>
                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                    </svg>
                </button>
            </div>
        `;

    // 添加事件监听器
    this.attachTaskEventListeners(taskElement, task);

    return taskElement;
  }

  /**
   * 为任务元素添加事件监听器
   */
  private attachTaskEventListeners(element: HTMLElement, task: Task): void {
    const checkbox = element.querySelector(
      'input[type="checkbox"]'
    ) as HTMLInputElement;
    const playBtn = element.querySelector(
      '.task-action-btn.play'
    ) as HTMLElement;
    const editBtn = element.querySelector(
      '.task-action-btn.edit'
    ) as HTMLElement;
    const deleteBtn = element.querySelector(
      '.task-action-btn.delete'
    ) as HTMLElement;

    // Use addEventListener to track these
    this.addEventListener(checkbox, 'change', () => {
      this.toggleTaskComplete(task.id);
    });

    this.addEventListener(playBtn, 'click', () => {
      this.setActiveTask(task.id);
    });

    this.addEventListener(editBtn, 'click', () => {
      eventEmitter.emit('task:edit', task);
    });

    this.addEventListener(deleteBtn, 'click', () => {
      this.confirmDelete(task);
    });
  }

  /**
   * 添加任务
   */
  public addTask(task: Task): void {
    this.tasks.push(task);
    this.render();
    toastManager.success('任务已创建', `"${task.title}" 已添加到列表`);
  }

  /**
   * 更新任务
   */
  public updateTask(task: Task): void {
    const index = this.tasks.findIndex((t) => t.id === task.id);
    if (index !== -1) {
      this.tasks[index] = task;
      this.render();
      toastManager.success('任务已更新', `"${task.title}" 更新成功`);
    }
  }

  /**
   * 删除任务
   */
  public deleteTask(id: string): void {
    const task = this.tasks.find((t) => t.id === id);
    this.tasks = this.tasks.filter((t) => t.id !== id);

    if (this.activeTaskId === id) {
      this.activeTaskId = null;
    }

    this.render();

    if (task) {
      toastManager.info('任务已删除', `"${task.title}" 已从列表中移除`);
    }
  }

  /**
   * 切换任务完成状态
   */
  public toggleTaskComplete(id: string): void {
    const task = this.tasks.find((t) => t.id === id);
    if (task) {
      const isCompleted = task.status === 'completed';
      task.status = isCompleted ? 'active' : 'completed';
      task.completedAt = isCompleted ? undefined : new Date();

      if (isCompleted) {
        toastManager.info('任务已恢复', `"${task.title}" 已恢复为进行中`);
      } else {
        toastManager.success('任务已完成', `恭喜！完成 "${task.title}"`);
        eventEmitter.emit('task:completed', task);
      }

      this.render();
    }
  }

  /**
   * 设置活动任务
   */
  public setActiveTask(id: string): void {
    const task = this.tasks.find((t) => t.id === id);
    if (task) {
      this.activeTaskId = id;
      this.render();

      // 更新当前任务显示
      const currentTaskDisplay = document.getElementById(
        'current-task-display'
      );
      if (currentTaskDisplay) {
        currentTaskDisplay.innerHTML = `
                    <p class="current-task-text active">当前任务：${this.escapeHtml(task.title)}</p>
                `;
      }

      toastManager.success('任务已激活', `开始专注：${task.title}`);
      eventEmitter.emit('task:activated', task);
    }
  }

  /**
   * 确认删除任务
   */
  private confirmDelete(task: Task): void {
    toastManager.warning(
      '确认删除',
      `确定要删除任务 "${task.title}" 吗？`,
      false
    );

    // 添加确认按钮
    const lastToast = this.getLastToast();
    if (lastToast) {
      const actions: Array<{
        label: string;
        onClick: () => void;
        primary: boolean;
      }> = [
        {
          label: '取消',
          onClick: () => {},
          primary: false,
        },
        {
          label: '删除',
          onClick: () => this.deleteTask(task.id),
          primary: true,
        },
      ];

      // 更新 toast 的操作按钮
      const toastContainer = document.getElementById('toast-container');
      const toastElement = toastContainer?.lastElementChild as HTMLElement;
      if (toastElement) {
        const actionsDiv = document.createElement('div');
        actionsDiv.className = 'toast-actions';
        actionsDiv.style.marginTop = '12px';
        actionsDiv.style.display = 'flex';
        actionsDiv.style.gap = '8px';

        actions.forEach((action) => {
          const btn = document.createElement('button');
          btn.className = `btn ${action.primary ? 'btn-danger' : 'btn-secondary'} btn-small`;
          btn.textContent = action.label;
          btn.onclick = () => {
            action.onClick();
            toastManager.hide(toastElement);
          };
          actionsDiv.appendChild(btn);
        });

        const content = toastElement.querySelector('.toast-content');
        content?.appendChild(actionsDiv);
      }
    }
  }

  /**
   * 获取最后一个 toast 元素
   */
  private getLastToast(): HTMLElement | null {
    const toastContainer = document.getElementById('toast-container');
    return (toastContainer?.lastElementChild as HTMLElement) || null;
  }

  /**
   * 更新任务计数
   */
  private updateCounts(): void {
    const allCount = this.tasks.length;
    const activeCount = this.tasks.filter((t) => t.status === 'active').length;
    const completedCount = this.tasks.filter(
      (t) => t.status === 'completed'
    ).length;

    document.getElementById('count-all')!.textContent = allCount.toString();
    document.getElementById('count-active')!.textContent =
      activeCount.toString();
    document.getElementById('count-completed')!.textContent =
      completedCount.toString();
  }

  /**
   * 获取优先级标签
   */
  private getPriorityLabel(priority: string): string {
    const labels: Record<string, string> = {
      high: '高',
      medium: '中',
      low: '低',
    };
    return labels[priority] || priority;
  }

  /**
   * 转义 HTML
   */
  private escapeHtml(text: string): string {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  /**
   * 获取所有任务
   */
  public getTasks(): Task[] {
    return this.tasks;
  }

  /**
   * 获取活动任务
   */
  public getActiveTask(): Task | null {
    return this.activeTaskId
      ? this.tasks.find((t) => t.id === this.activeTaskId) || null
      : null;
  }
}

/**
 * 计时器显示组件
 */

import { TimerInfo, TimerMode, TimerState } from '../types';
import { eventEmitter } from '../utils/EventEmitter';

export class TimerDisplay {
  private container: HTMLElement;
  private minutesElement: HTMLElement;
  private secondsElement: HTMLElement;
  statusElement: HTMLElement;
  private progressRing: HTMLElement;
  private timerStatus: HTMLElement;
  private statusIndicator: HTMLElement;
  private statusText: HTMLElement;
  private currentTaskDisplay: HTMLElement;

  // 进度环周长
  private readonly CIRCUMFERENCE = 2 * Math.PI * 90; // r=90

  constructor() {
    this.container = document.getElementById('timer-display')!;
    this.minutesElement = document.getElementById('timer-minutes')!;
    this.secondsElement = document.getElementById('timer-seconds')!;
    this.statusElement = document.getElementById('timer-status')!;
    this.progressRing = document.getElementById('progress-ring')!;
    this.timerStatus = document.querySelector('.timer-status')!;
    this.statusIndicator = document.querySelector('.status-indicator')!;
    this.statusText = document.querySelector('.status-text')!;
    this.currentTaskDisplay = document.getElementById('current-task-display')!;

    this.initializeEventListeners();
  }

  /**
   * 初始化事件监听器
   */
  private initializeEventListeners(): void {
    // 监听模式切换
    const modeButtons = document.querySelectorAll('.mode-btn');
    modeButtons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const mode = btn.getAttribute('data-mode') as TimerMode;
        this.setMode(mode);
        eventEmitter.emit('timer:modeChange', mode);
      });
    });

    // 监听计时器事件
    eventEmitter.on('timer:start', () => this.setState('running'));
    eventEmitter.on('timer:pause', () => this.setState('paused'));
    eventEmitter.on('timer:reset', () => this.setState('idle'));
    eventEmitter.on('timer:complete', () => this.onComplete());
  }

  /**
   * 更新时间显示
   */
  public updateTime(timeRemaining: number, totalTime: number): void {
    const minutes = Math.floor(timeRemaining / 60);
    const seconds = timeRemaining % 60;

    this.minutesElement.textContent = minutes.toString().padStart(2, '0');
    this.secondsElement.textContent = seconds.toString().padStart(2, '0');

    // 更新进度环
    this.updateProgress(timeRemaining, totalTime);
  }

  /**
   * 更新进度环
   */
  private updateProgress(timeRemaining: number, totalTime: number): void {
    const progress = (totalTime - timeRemaining) / totalTime;
    const offset = this.CIRCUMFERENCE * (1 - progress);
    this.progressRing.style.strokeDashoffset = offset.toString();
  }

  /**
   * 更新状态
   */
  public setState(state: TimerState): void {
    this.statusIndicator.classList.remove('paused', 'break');
    this.statusIndicator.classList.add('running');

    const toggleBtn = document.getElementById('timer-toggle-btn');
    const btnIcon = toggleBtn?.querySelector('.btn-icon');
    const btnText = toggleBtn?.querySelector('.btn-text');

    switch (state) {
      case 'idle':
        this.statusText.textContent = '准备就绪';
        this.statusIndicator.classList.remove('running');
        this.statusIndicator.style.backgroundColor = 'var(--color-success)';
        if (toggleBtn) {
          toggleBtn.setAttribute('aria-label', '开始计时');
          if (btnIcon) btnIcon.textContent = '▶';
          if (btnText) btnText.textContent = '开始';
        }
        break;

      case 'running':
        this.statusText.textContent = '专注中...';
        this.statusIndicator.style.backgroundColor = 'var(--color-success)';
        if (toggleBtn) {
          toggleBtn.setAttribute('aria-label', '暂停计时');
          if (btnIcon) btnIcon.textContent = '⏸';
          if (btnText) btnText.textContent = '暂停';
        }
        break;

      case 'paused':
        this.statusText.textContent = '已暂停';
        this.statusIndicator.classList.add('paused');
        this.statusIndicator.classList.remove('running');
        this.statusIndicator.style.backgroundColor = 'var(--color-warning)';
        if (toggleBtn) {
          toggleBtn.setAttribute('aria-label', '继续计时');
          if (btnIcon) btnIcon.textContent = '▶';
          if (btnText) btnText.textContent = '继续';
        }
        break;

      case 'completed':
        this.statusText.textContent = '已完成';
        this.statusIndicator.classList.remove('running');
        this.statusIndicator.style.backgroundColor = 'var(--color-success)';
        break;
    }
  }

  /**
   * 设置计时器模式
   */
  public setMode(mode: TimerMode): void {
    // 更新按钮状态
    const modeButtons = document.querySelectorAll('.mode-btn');
    modeButtons.forEach((btn) => {
      const btnMode = btn.getAttribute('data-mode');
      const isActive = btnMode === mode;
      btn.classList.toggle('mode-btn-active', isActive);
      btn.setAttribute('aria-selected', isActive.toString());
    });

    // 更新进度环颜色
    if (mode === 'shortBreak' || mode === 'longBreak') {
      this.progressRing.classList.add('break');
      this.statusIndicator.classList.add('break');
    } else {
      this.progressRing.classList.remove('break');
      this.statusIndicator.classList.remove('break');
    }
  }

  /**
   * 完成时的效果
   */
  private onComplete(): void {
    this.setState('completed');
    this.flashScreen();
    this.playSound();
  }

  /**
   * 屏幕闪烁提醒
   */
  public flashScreen(color?: string): void {
    const flashColor = color || 'var(--color-primary-light)';
    const flashOverlay = document.createElement('div');
    flashOverlay.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: ${flashColor};
            opacity: 0.5;
            z-index: 9999;
            pointer-events: none;
            animation: flash 0.5s ease-in-out 3;
        `;

    document.body.appendChild(flashOverlay);

    setTimeout(() => {
      document.body.removeChild(flashOverlay);
    }, 1500);
  }

  /**
   * 播放提示音
   */
  private playSound(): void {
    // 使用 Web Audio API 生成提示音
    try {
      const audioContext = new (
        window.AudioContext || (window as any).webkitAudioContext
      )();
      const oscillator = audioContext.createOscillator();
      const gainNode = audioContext.createGain();

      oscillator.connect(gainNode);
      gainNode.connect(audioContext.destination);

      oscillator.frequency.value = 800;
      oscillator.type = 'sine';

      gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(
        0.01,
        audioContext.currentTime + 0.5
      );

      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.5);
    } catch (error) {
      console.error('Error playing sound:', error);
    }
  }

  /**
   * 显示进度
   */
  public showProgress(percent: number): void {
    // 这个方法可以用于显示更详细的进度信息
    const offset = this.CIRCUMFERENCE * (1 - percent / 100);
    this.progressRing.style.strokeDashoffset = offset.toString();
  }

  /**
   * 重置进度环
   */
  public resetProgress(): void {
    this.progressRing.style.strokeDashoffset = '0';
  }

  /**
   * 更新当前任务显示
   */
  public updateCurrentTask(taskTitle?: string): void {
    if (taskTitle) {
      this.currentTaskDisplay.innerHTML = `
                <p class="current-task-text active">当前任务：${this.escapeHtml(taskTitle)}</p>
            `;
    } else {
      this.currentTaskDisplay.innerHTML = `
                <p class="current-task-text">选择一个任务开始专注</p>
            `;
    }
  }

  /**
   * 转义 HTML
   */
  private escapeHtml(text: string): string {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  /**
   * 获取时间元素
   */
  public getTimeElements(): { minutes: HTMLElement; seconds: HTMLElement } {
    return {
      minutes: this.minutesElement,
      seconds: this.secondsElement,
    };
  }
}

/**
 * TimerController - Manages the Pomodoro Timer logic
 *
 * Responsibilities:
 * - Controlling timer start/pause/reset/skip
 * - Managing interval timing
 * - Handling session completion
 * - Coordinating with AppStore for state updates
 * - Managing notification permissions and delivery
 */

import {
  TimerState,
  SessionType,
  TimerEventType,
  TimerEvent,
  TimerObserver,
  TimerSettings,
} from '../types/index';
import { AppStore } from '../store/AppStore';

/**
 * Audio notification types
 */
enum AudioNotification {
  WORK_START = 'work_start',
  WORK_COMPLETE = 'work_complete',
  BREAK_START = 'break_start',
  BREAK_COMPLETE = 'break_complete',
}

/**
 * Timer controller configuration
 */
export interface TimerControllerConfig {
  store: AppStore;
  onTick?: (remainingTime: number) => void;
  onSessionComplete?: (sessionType: SessionType) => void;
  notificationEnabled?: boolean;
  soundEnabled?: boolean;
}

/**
 * TimerController - Main timer management class
 */
export class TimerController {
  private store: AppStore;
  private onTick?: (remainingTime: number) => void;
  private onSessionComplete?: (sessionType: SessionType) => void;

  // Timer interval reference
  private intervalId: number | null = null;
  private tickIntervalMs: number = 1000; // 1 second

  // Notification state
  private notificationPermission: NotificationPermission = 'default';
  private audioContext: AudioContext | null = null;

  // Observer management
  private observers: Set<TimerObserver> = new Set();

  // Background sync for keeping timer accurate
  private lastTickTime: number = 0;
  private driftCorrection: number = 0;

  // Visibility change handling for tab switching
  private wasRunningBeforeHidden: boolean = false;
  private tabHiddenTime: number = 0;

  constructor(config: TimerControllerConfig) {
    this.store = config.store;
    this.onTick = config.onTick;
    this.onSessionComplete = config.onSessionComplete;

    // Request notification permission if enabled
    if (config.notificationEnabled !== false) {
      this.requestNotificationPermission();
    }

    // Setup visibility change handler
    this.setupVisibilityHandler();

    // Subscribe to store changes
    this.store.subscribeToTimer(this.handleStoreTimerEvent.bind(this));
  }

  // ==========================================================================
  // PUBLIC API - Timer Control
  // ==========================================================================

  /**
   * Start the timer
   */
  async start(sessionType?: SessionType): Promise<void> {
    const state = this.store.getTimerState();

    // If already running, don't restart
    if (
      state === TimerState.WORKING ||
      state === TimerState.SHORT_BREAK ||
      state === TimerState.LONG_BREAK
    ) {
      return;
    }

    // Determine session type
    const targetSessionType = sessionType || this.determineNextSessionType();

    // Start timer via store
    await this.store.startTimer(targetSessionType);

    // Start the interval
    this.startInterval();

    // Play sound
    this.playAudio(
      targetSessionType === SessionType.WORK
        ? AudioNotification.WORK_START
        : AudioNotification.BREAK_START
    );

    // Show notification
    this.showNotification(this.getSessionStartMessage(targetSessionType));
  }

  /**
   * Pause the timer
   */
  async pause(): Promise<void> {
    const state = this.store.getTimerState();

    if (state === TimerState.IDLE || state === TimerState.PAUSED) {
      return;
    }

    // Pause via store
    await this.store.pauseTimer();

    // Stop interval
    this.stopInterval();

    // Play pause sound
    this.playAudio(AudioNotification.WORK_COMPLETE);
  }

  /**
   * Resume the timer
   */
  async resume(): Promise<void> {
    const state = this.store.getTimerState();

    if (state !== TimerState.PAUSED) {
      return;
    }

    // Resume via store
    await this.store.resumeTimer();

    // Restart interval
    this.startInterval();
  }

  /**
   * Reset the timer
   */
  async reset(): Promise<void> {
    // Reset via store
    await this.store.resetTimer();

    // Stop interval
    this.stopInterval();
  }

  /**
   * Skip current session
   */
  async skip(): Promise<void> {
    const state = this.store.getTimerState();

    if (state === TimerState.IDLE) {
      return;
    }

    const sessionType = this.store.getCurrentSessionType();

    // Skip via store
    await this.store.skipSession();

    // Stop interval
    this.stopInterval();

    // Notify callback
    if (this.onSessionComplete && sessionType) {
      this.onSessionComplete(sessionType);
    }
  }

  /**
   * Toggle timer (start/pause)
   */
  async toggle(): Promise<void> {
    const state = this.store.getTimerState();

    if (state === TimerState.IDLE || state === TimerState.PAUSED) {
      await this.start();
    } else {
      await this.pause();
    }
  }

  // ==========================================================================
  // TIMER INTERVAL MANAGEMENT
  // ==========================================================================

  /**
   * Start the tick interval
   */
  private startInterval(): void {
    // Clear any existing interval
    this.stopInterval();

    this.lastTickTime = Date.now();

    // Use requestAnimationFrame for smoother UI updates
    // while still tracking actual time
    this.intervalId = window.setInterval(() => {
      this.tick();
    }, this.tickIntervalMs);
  }

  /**
   * Stop the tick interval
   */
  private stopInterval(): void {
    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  /**
   * Timer tick - called every second
   */
  private tick(): void {
    const now = Date.now();
    const elapsed = now - this.lastTickTime;
    this.lastTickTime = now;

    // Handle drift correction
    this.driftCorrection += elapsed - this.tickIntervalMs;

    // Only tick if we've accumulated enough drift
    if (Math.abs(this.driftCorrection) >= 100) {
      // Correct for accumulated drift
      if (this.driftCorrection > 0) {
        // Running slow, skip a tick
        this.driftCorrection -= this.tickIntervalMs;
      }
    }

    // Update remaining time in store
    this.store.tickTimer();

    // Get updated state
    const remainingTime = this.store.getRemainingTime();

    // Notify tick callback
    if (this.onTick) {
      this.onTick(remainingTime);
    }

    // Check if timer completed
    if (remainingTime <= 0) {
      this.handleTimerComplete();
    }
  }

  /**
   * Handle timer completion
   */
  private async handleTimerComplete(): Promise<void> {
    // Stop interval
    this.stopInterval();

    const sessionType = this.store.getCurrentSessionType();
    const settings = this.store.getSettings();

    // Play completion sound
    this.playAudio(
      sessionType === SessionType.WORK
        ? AudioNotification.WORK_COMPLETE
        : AudioNotification.BREAK_COMPLETE
    );

    // Show notification
    this.showNotification(this.getSessionCompleteMessage(sessionType));

    // Notify callback
    if (this.onSessionComplete && sessionType) {
      this.onSessionComplete(sessionType);
    }

    // Auto-start next session if enabled
    const nextSessionType = this.determineNextSessionType();

    if (sessionType === SessionType.WORK && settings.autoStartBreak) {
      // Auto-start break after work
      setTimeout(() => {
        this.start(nextSessionType);
      }, 1000);
    } else if (sessionType !== SessionType.WORK && settings.autoStartWork) {
      // Auto-start work after break
      setTimeout(() => {
        this.start(SessionType.WORK);
      }, 1000);
    }
  }

  // ==========================================================================
  // SESSION TYPE LOGIC
  // ==========================================================================

  /**
   * Determine the next session type based on settings and history
   */
  private determineNextSessionType(): SessionType {
    const settings = this.store.getSettings();
    const currentState = this.store.getTimerState();
    const currentSession = this.store.getCurrentSessionType();
    const completedSessions =
      this.store.getState().completedSessionsSinceLastLongBreak;

    // If currently idle, start with work
    if (currentState === TimerState.IDLE && !currentSession) {
      return SessionType.WORK;
    }

    // If just completed a work session, determine break type
    if (
      currentState === TimerState.IDLE &&
      currentSession === SessionType.WORK
    ) {
      // Check if we need a long break
      if (completedSessions >= settings.longBreakInterval) {
        return SessionType.LONG_BREAK;
      }
      return SessionType.SHORT_BREAK;
    }

    // If just completed a break, return to work
    if (
      currentState === TimerState.IDLE &&
      (currentSession === SessionType.SHORT_BREAK ||
        currentSession === SessionType.LONG_BREAK)
    ) {
      return SessionType.WORK;
    }

    // Default to work
    return SessionType.WORK;
  }

  /**
   * Get the duration for a session type
   */
  getDuration(sessionType: SessionType): number {
    const settings = this.store.getSettings();

    switch (sessionType) {
      case SessionType.WORK:
        return settings.workDuration;
      case SessionType.SHORT_BREAK:
        return settings.shortBreakDuration;
      case SessionType.LONG_BREAK:
        return settings.longBreakDuration;
    }
  }

  // ==========================================================================
  // NOTIFICATIONS
  // ==========================================================================

  /**
   * Request notification permission
   */
  private async requestNotificationPermission(): Promise<void> {
    if ('Notification' in window) {
      this.notificationPermission = await Notification.requestPermission();
    }
  }

  /**
   * Show a notification
   */
  private showNotification(message: string): void {
    const settings = this.store.getSettings();

    if (!settings.notificationEnabled) {
      return;
    }

    if (this.notificationPermission !== 'granted') {
      return;
    }

    // Use browser notification
    if ('Notification' in window) {
      new Notification('Pomodoro Timer', {
        body: message,
        icon: this.getNotificationIcon(),
        badge: this.getNotificationIcon(),
        tag: 'pomodoro-timer',
      });
    }
  }

  /**
   * Get notification icon URL
   */
  private getNotificationIcon(): string {
    // Return a default icon or your app's icon
    return '/icons/icon-192.png';
  }

  /**
   * Get session start message
   */
  private getSessionStartMessage(sessionType: SessionType): string {
    switch (sessionType) {
      case SessionType.WORK:
        return "Time to focus! Let's get to work.";
      case SessionType.SHORT_BREAK:
        return 'Great work! Take a short break.';
      case SessionType.LONG_BREAK:
        return 'Excellent progress! Time for a longer break.';
    }
  }

  /**
   * Get session complete message
   */
  private getSessionCompleteMessage(sessionType: SessionType | null): string {
    switch (sessionType) {
      case SessionType.WORK:
        return 'Work session complete! Take a break.';
      case SessionType.SHORT_BREAK:
      case SessionType.LONG_BREAK:
        return 'Break over! Ready to focus again?';
      default:
        return 'Timer complete!';
    }
  }

  // ==========================================================================
  // AUDIO NOTIFICATIONS
  // ==========================================================================

  /**
   * Play audio notification
   */
  private playAudio(type: AudioNotification): void {
    const settings = this.store.getSettings();

    if (!settings.soundEnabled) {
      return;
    }

    // Initialize audio context if needed
    if (!this.audioContext) {
      this.audioContext = new (
        window.AudioContext || (window as any).webkitAudioContext
      )();
    }

    // Play sound based on type
    switch (type) {
      case AudioNotification.WORK_START:
        this.playTone(880, 0.1, 'sine'); // A5
        break;
      case AudioNotification.WORK_COMPLETE:
        this.playTone(523, 0.15, 'sine'); // C5
        setTimeout(() => this.playTone(659, 0.15, 'sine'), 150); // E5
        setTimeout(() => this.playTone(784, 0.2, 'sine'), 300); // G5
        break;
      case AudioNotification.BREAK_START:
        this.playTone(659, 0.1, 'sine'); // E5
        break;
      case AudioNotification.BREAK_COMPLETE:
        this.playTone(784, 0.15, 'sine'); // G5
        setTimeout(() => this.playTone(659, 0.15, 'sine'), 150); // E5
        break;
    }
  }

  /**
   * Play a tone with specified frequency and duration
   */
  private playTone(
    frequency: number,
    duration: number,
    type: OscillatorType = 'sine'
  ): void {
    if (!this.audioContext) return;

    const settings = this.store.getSettings();
    const volume = settings.volume;

    try {
      const oscillator = this.audioContext.createOscillator();
      const gainNode = this.audioContext.createGain();

      oscillator.connect(gainNode);
      gainNode.connect(this.audioContext.destination);

      oscillator.frequency.value = frequency;
      oscillator.type = type;

      // Envelope to avoid clicking
      const now = this.audioContext.currentTime;
      gainNode.gain.setValueAtTime(0, now);
      gainNode.gain.linearRampToValueAtTime(volume, now + 0.01);
      gainNode.gain.exponentialRampToValueAtTime(0.001, now + duration);

      oscillator.start(now);
      oscillator.stop(now + duration);
    } catch (error) {
      console.error('Error playing tone:', error);
    }
  }

  // ==========================================================================
  // TAB VISIBILITY HANDLING
  // ==========================================================================

  /**
   * Setup visibility change handler for tab switching
   */
  private setupVisibilityHandler(): void {
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        this.handleTabHidden();
      } else {
        this.handleTabVisible();
      }
    });
  }

  /**
   * Handle tab hidden
   */
  private handleTabHidden(): void {
    const state = this.store.getTimerState();

    // Save state if timer was running
    if (
      state === TimerState.WORKING ||
      state === TimerState.SHORT_BREAK ||
      state === TimerState.LONG_BREAK
    ) {
      this.wasRunningBeforeHidden = true;
      this.tabHiddenTime = Date.now();
    } else {
      this.wasRunningBeforeHidden = false;
    }
  }

  /**
   * Handle tab visible
   */
  private handleTabVisible(): void {
    if (!this.wasRunningBeforeHidden) {
      return;
    }

    // Calculate time elapsed while hidden
    const elapsed = Date.now() - this.tabHiddenTime;
    const remainingTime = this.store.getRemainingTime();

    // If enough time passed, the session should be complete
    if (elapsed >= remainingTime * 1000) {
      // Session completed while hidden
      this.handleTimerComplete();
    }
  }

  // ==========================================================================
  // OBSERVER MANAGEMENT
  // ==========================================================================

  /**
   * Subscribe to timer events
   */
  subscribe(observer: TimerObserver): () => void {
    this.observers.add(observer);

    // Return unsubscribe function
    return () => {
      this.observers.delete(observer);
    };
  }

  /**
   * Handle timer events from store
   */
  private handleStoreTimerEvent(event: TimerEvent): void {
    // Notify all observers
    this.observers.forEach((observer) => {
      try {
        observer(event);
      } catch (error) {
        console.error('Error in timer observer:', error);
      }
    });
  }

  // ==========================================================================
  // CLEANUP
  // ==========================================================================

  /**
   * Cleanup and destroy the controller
   */
  destroy(): void {
    this.stopInterval();

    // Clear observers
    this.observers.clear();

    // Close audio context
    if (this.audioContext) {
      this.audioContext.close();
      this.audioContext = null;
    }
  }

  // ==========================================================================
  // UTILITY METHODS
  // ==========================================================================

  /**
   * Format time as MM:SS
   */
  static formatTime(seconds: number): string {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  /**
   * Format time as HH:MM:SS
   */
  static formatTimeLong(seconds: number): string {
    const hours = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    if (hours > 0) {
      return `${hours}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    }
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  /**
   * Get percentage completed
   */
  getPercentageCompleted(): number {
    const remainingTime = this.store.getRemainingTime();
    const sessionType = this.store.getCurrentSessionType();
    const totalTime = sessionType
      ? this.getDuration(sessionType)
      : remainingTime;

    if (totalTime === 0) return 0;

    return Math.round(((totalTime - remainingTime) / totalTime) * 100);
  }

  /**
   * Get estimated completion time
   */
  getEstimatedCompletionTime(): Date | null {
    const state = this.store.getTimerState();

    if (state === TimerState.IDLE || state === TimerState.PAUSED) {
      return null;
    }

    const remainingTime = this.store.getRemainingTime();
    return new Date(Date.now() + remainingTime * 1000);
  }
}

/**
 * UIController - Manages UI updates and rendering
 *
 * Responsibilities:
 * - Rendering task lists
 * - Updating timer display
 * - Displaying statistics
 * - Managing modals and toasts
 * - Handling theme changes
 * - Coordinating with DOM elements
 */

import {
  Task,
  TaskStatus,
  TaskPriority,
  TimerState,
  SessionType,
  Statistics,
  Toast,
  ToastType,
  AppState,
} from '../types/index';
import { AppStore } from '../store/AppStore';

/**
 * UI element references
 */
interface UIElements {
  // Timer elements
  timerDisplay: HTMLElement | null;
  timerState: HTMLElement | null;
  timerProgressBar: HTMLElement | null;
  timerSessionType: HTMLElement | null;
  startButton: HTMLElement | null;
  pauseButton: HTMLElement | null;
  resetButton: HTMLElement | null;
  skipButton: HTMLElement | null;

  // Task elements
  taskList: HTMLElement | null;
  taskForm: HTMLFormElement | null;
  taskInput: HTMLInputElement | null;
  activeTaskDisplay: HTMLElement | null;

  // Statistics elements
  statsPanel: HTMLElement | null;
  todayPomodoros: HTMLElement | null;
  todayFocusTime: HTMLElement | null;
  todayCompletedTasks: HTMLElement | null;

  // Modal elements
  modalOverlay: HTMLElement | null;
  modalContainer: HTMLElement | null;
  modalTitle: HTMLElement | null;
  modalContent: HTMLElement | null;
  modalClose: HTMLElement | null;

  // Toast elements
  toastContainer: HTMLElement | null;
}

/**
 * UI Controller Configuration
 */
export interface UIControllerConfig {
  store: AppStore;
  elements?: Partial<UIElements>;
  autoBind?: boolean;
  enableAnimations?: boolean;
}

/**
 * Component render function type
 */
type ComponentRenderFn<T> = (data: T, element: HTMLElement) => void;

/**
 * UIController - Main UI management class
 */
export class UIController {
  private store: AppStore;
  private elements: UIElements;
  private autoBind: boolean;
  private enableAnimations: boolean;

  // Component renderers
  private taskRenderers: Map<string, ComponentRenderFn<any>> = new Map();
  private statRenderers: Map<string, ComponentRenderFn<any>> = new Map();

  // Toast management
  private activeToasts: Map<string, HTMLElement> = new Map();
  private toastCounter: number = 0;

  // Current theme
  private currentTheme: 'light' | 'dark' = 'light';

  // Unsubscribe function for store
  private unsubscribeStore?: () => void;

  constructor(config: UIControllerConfig) {
    this.store = config.store;
    this.autoBind = config.autoBind ?? true;
    this.enableAnimations = config.enableAnimations ?? true;

    // Initialize elements
    this.elements = {
      timerDisplay:
        config.elements?.timerDisplay ||
        document.getElementById('timer-display'),
      timerState:
        config.elements?.timerState || document.getElementById('timer-state'),
      timerProgressBar:
        config.elements?.timerProgressBar ||
        document.getElementById('timer-progress'),
      timerSessionType:
        config.elements?.timerSessionType ||
        document.getElementById('timer-session-type'),
      startButton:
        config.elements?.startButton || document.getElementById('start-button'),
      pauseButton:
        config.elements?.pauseButton || document.getElementById('pause-button'),
      resetButton:
        config.elements?.resetButton || document.getElementById('reset-button'),
      skipButton:
        config.elements?.skipButton || document.getElementById('skip-button'),
      taskList:
        config.elements?.taskList || document.getElementById('task-list'),
      taskForm:
        config.elements?.taskForm ||
        (document.getElementById('task-form') as HTMLFormElement),
      taskInput:
        config.elements?.taskInput ||
        (document.getElementById('task-input') as HTMLInputElement),
      activeTaskDisplay:
        config.elements?.activeTaskDisplay ||
        document.getElementById('active-task'),
      statsPanel:
        config.elements?.statsPanel || document.getElementById('stats-panel'),
      todayPomodoros:
        config.elements?.todayPomodoros ||
        document.getElementById('today-pomodoros'),
      todayFocusTime:
        config.elements?.todayFocusTime ||
        document.getElementById('today-focus-time'),
      todayCompletedTasks:
        config.elements?.todayCompletedTasks ||
        document.getElementById('today-completed-tasks'),
      modalOverlay:
        config.elements?.modalOverlay ||
        document.getElementById('modal-overlay'),
      modalContainer:
        config.elements?.modalContainer ||
        document.getElementById('modal-container'),
      modalTitle:
        config.elements?.modalTitle || document.getElementById('modal-title'),
      modalContent:
        config.elements?.modalContent ||
        document.getElementById('modal-content'),
      modalClose:
        config.elements?.modalClose || document.getElementById('modal-close'),
      toastContainer:
        config.elements?.toastContainer ||
        document.getElementById('toast-container'),
    };

    // Create toast container if it doesn't exist
    this.ensureToastContainer();

    // Subscribe to store changes
    this.unsubscribeStore = this.store.subscribe(
      this.handleStateChange.bind(this)
    );

    // Auto-bind elements if enabled
    if (this.autoBind) {
      this.bindElements();
    }

    // Initial render
    this.renderAll();
  }

  // ==========================================================================
  // STATE CHANGE HANDLING
  // ==========================================================================

  /**
   * Handle state changes from store
   */
  private handleStateChange(state: Readonly<AppState>): void {
    this.renderAll();
  }

  /**
   * Render all UI elements
   */
  renderAll(): void {
    const state = this.store.getState();

    this.renderTasks(state.tasks);
    this.updateTimer(state.remainingTime, state.timerState);
    this.updateStatistics(this.store.getStatistics());
    this.updateActiveTask();
  }

  // ==========================================================================
  // TASK LIST RENDERING
  // ==========================================================================

  /**
   * Render task list
   */
  renderTasks(tasks: Task[]): void {
    const taskList = this.elements.taskList;
    if (!taskList) return;

    // Clear existing content
    taskList.innerHTML = '';

    if (tasks.length === 0) {
      this.renderEmptyState(taskList);
      return;
    }

    // Sort tasks by status and priority
    const sortedTasks = this.sortTasks(tasks);

    // Create task elements
    sortedTasks.forEach((task) => {
      const taskElement = this.createTaskElement(task);
      taskList.appendChild(taskElement);
    });

    // Apply animation if enabled
    if (this.enableAnimations) {
      this.animateListItems(taskList);
    }
  }

  /**
   * Create a task element
   */
  private createTaskElement(task: Task): HTMLElement {
    const li = document.createElement('div');
    li.className = `task-item task-${task.status} priority-${task.priority}`;
    li.dataset.taskId = task.id;

    const isActive = this.store.getActiveTask()?.id === task.id;
    if (isActive) {
      li.classList.add('active');
    }

    li.innerHTML = `
      <div class="task-checkbox">
        <input type="checkbox" ${task.status === TaskStatus.COMPLETED ? 'checked' : ''}>
      </div>
      <div class="task-content">
        <div class="task-title">${this.escapeHtml(task.title)}</div>
        ${task.description ? `<div class="task-description">${this.escapeHtml(task.description)}</div>` : ''}
        <div class="task-meta">
          <span class="task-priority badge badge-${task.priority}">${task.priority}</span>
          ${task.estimatedPomodoros ? `<span class="task-estimates"><span class="pomodoro-icon"></span>${task.completedPomodoros}/${task.estimatedPomodoros}</span>` : ''}
        </div>
      </div>
      <div class="task-actions">
        <button class="btn-icon btn-activate" title="Activate task">
          <svg width="16" height="16" viewBox="0 0 16 16"><path d="M8 0a8 8 0 100 16A8 8 0 008 0zm0 14a6 6 0 110-12 6 6 0 010 12zm0-8a2 2 0 100 4 2 2 0 000-4z"/></svg>
        </button>
        <button class="btn-icon btn-edit" title="Edit task">
          <svg width="16" height="16" viewBox="0 0 16 16"><path d="M12.854 3.146a.5.5 0 00-.708 0L10 5.293 8.854 4.146a.5.5 0 00-.708 0l-6 6A.5.5 0 002 11.5v3a.5.5 0 00.5.5h3a.5.5 0 00.354-.146l6-6a.5.5 0 000-.708L10 7.707l2.146-2.147a.5.5 0 000-.707l-.292-.293z"/></svg>
        </button>
        <button class="btn-icon btn-delete" title="Delete task">
          <svg width="16" height="16" viewBox="0 0 16 16"><path d="M5.5 5.5A.5.5 0 016 6v6a.5.5 0 01-1 0V6a.5.5 0 01.5-.5zm2.5 0a.5.5 0 01.5.5v6a.5.5 0 01-1 0V6a.5.5 0 01.5-.5zm3 .5a.5.5 0 00-1 0v6a.5.5 0 001 0V6z"/><path fill-rule="evenodd" d="M14.5 3a1 1 0 01-1 1H13v9a2 2 0 01-2 2H5a2 2 0 01-2-2V4h-.5a1 1 0 01-1-1V2a1 1 0 011-1H6a1 1 0 011-1h2a1 1 0 011 1h3.5a1 1 0 011 1v1zM4.118 4L4 4.059V13a1 1 0 001 1h6a1 1 0 001-1V4.059L11.882 4H4.118zM2.5 3V2h11v1h-11z"/></svg>
        </button>
      </div>
    `;

    // Add event listeners
    this.attachTaskEventListeners(li, task);

    return li;
  }

  /**
   * Attach event listeners to task element
   */
  private attachTaskEventListeners(element: HTMLElement, task: Task): void {
    const checkbox = element.querySelector(
      '.task-checkbox input'
    ) as HTMLInputElement;
    const activateBtn = element.querySelector('.btn-activate') as HTMLElement;
    const editBtn = element.querySelector('.btn-edit') as HTMLElement;
    const deleteBtn = element.querySelector('.btn-delete') as HTMLElement;

    checkbox?.addEventListener('change', async () => {
      if (checkbox.checked) {
        await this.store.completeTask(task.id);
      } else {
        await this.store.updateTask(task.id, { status: TaskStatus.TODO });
      }
    });

    activateBtn?.addEventListener('click', async () => {
      await this.store.setActiveTask(task.id);
    });

    editBtn?.addEventListener('click', () => {
      this.showEditTaskModal(task);
    });

    deleteBtn?.addEventListener('click', async () => {
      const confirmed = await this.showConfirmDialog(
        'Delete Task',
        `Are you sure you want to delete "${task.title}"?`
      );
      if (confirmed) {
        await this.store.deleteTask(task.id);
      }
    });
  }

  /**
   * Render empty state
   */
  private renderEmptyState(container: HTMLElement): void {
    container.innerHTML = `
      <div class="empty-state">
        <div class="empty-state-icon"></div>
        <h3>No tasks yet</h3>
        <p>Create your first task to get started!</p>
        <button class="btn btn-primary" id="empty-state-add-task">Add Task</button>
      </div>
    `;

    container
      .querySelector('#empty-state-add-task')
      ?.addEventListener('click', () => {
        this.showAddTaskModal();
      });
  }

  /**
   * Sort tasks for display
   */
  private sortTasks(tasks: Task[]): Task[] {
    return [...tasks].sort((a, b) => {
      // Active task first
      const aActive = this.store.getActiveTask()?.id === a.id;
      const bActive = this.store.getActiveTask()?.id === b.id;
      if (aActive && !bActive) return -1;
      if (!aActive && bActive) return 1;

      // Then by completion status
      if (
        a.status === TaskStatus.COMPLETED &&
        b.status !== TaskStatus.COMPLETED
      )
        return 1;
      if (
        a.status !== TaskStatus.COMPLETED &&
        b.status === TaskStatus.COMPLETED
      )
        return -1;

      // Then by priority
      const priorityOrder = { urgent: 0, high: 1, medium: 2, low: 3 };
      const aPriority = priorityOrder[a.priority] ?? 2;
      const bPriority = priorityOrder[b.priority] ?? 2;
      if (aPriority !== bPriority) return aPriority - bPriority;

      // Finally by creation date
      return b.createdAt - a.createdAt;
    });
  }

  // ==========================================================================
  // TIMER UI UPDATES
  // ==========================================================================

  /**
   * Update timer display
   */
  updateTimer(time: number, state: TimerState): void {
    const display = this.elements.timerDisplay;
    const stateDisplay = this.elements.timerState;
    const progressBar = this.elements.timerProgressBar;
    const sessionType = this.elements.timerSessionType;

    // Update time display
    if (display) {
      display.textContent = this.formatTime(time);
    }

    // Update state display
    if (stateDisplay) {
      stateDisplay.textContent = this.getStateText(state);
      stateDisplay.className = `timer-state state-${state}`;
    }

    // Update progress bar
    if (progressBar) {
      const sessionTypeValue = this.store.getCurrentSessionType();
      const duration = sessionTypeValue
        ? this.getSessionDuration(sessionTypeValue)
        : time;
      const percentage =
        duration > 0 ? ((duration - time) / duration) * 100 : 0;
      progressBar.style.width = `${percentage}%`;
      progressBar.className = `timer-progress-bar state-${state}`;
    }

    // Update session type
    if (sessionType) {
      sessionType.textContent = this.getSessionTypeText();
    }

    // Update button states
    this.updateTimerButtons(state);
  }

  /**
   * Update timer button states
   */
  private updateTimerButtons(state: TimerState): void {
    const startBtn = this.elements.startButton;
    const pauseBtn = this.elements.pauseButton;
    const resetBtn = this.elements.resetButton;
    const skipBtn = this.elements.skipButton;

    // Start/pause button visibility
    if (startBtn && pauseBtn) {
      const isRunning =
        state === TimerState.WORKING ||
        state === TimerState.SHORT_BREAK ||
        state === TimerState.LONG_BREAK;

      startBtn.style.display =
        isRunning || state === TimerState.PAUSED ? 'none' : 'flex';
      pauseBtn.style.display = isRunning ? 'flex' : 'none';
    }

    // Reset and skip button states
    if (resetBtn) {
      resetBtn.disabled = state === TimerState.IDLE;
    }
    if (skipBtn) {
      skipBtn.disabled = state === TimerState.IDLE;
    }
  }

  /**
   * Update active task display
   */
  updateActiveTask(): void {
    const display = this.elements.activeTaskDisplay;
    if (!display) return;

    const activeTask = this.store.getActiveTask();

    if (activeTask) {
      display.innerHTML = `
        <div class="active-task-label">Focusing on:</div>
        <div class="active-task-title">${this.escapeHtml(activeTask.title)}</div>
        <div class="active-task-pomodoros">
          <span class="pomodoro-icon"></span>
          ${activeTask.completedPomodoros}${activeTask.estimatedPomodoros ? `/${activeTask.estimatedPomodoros}` : ''}
        </div>
      `;
      display.classList.add('has-active-task');
    } else {
      display.innerHTML = `
        <div class="active-task-placeholder">No active task</div>
      `;
      display.classList.remove('has-active-task');
    }
  }

  // ==========================================================================
  // STATISTICS UPDATES
  // ==========================================================================

  /**
   * Update statistics display
   */
  updateStatistics(stats: Statistics): void {
    // Today's stats
    if (this.elements.todayPomodoros) {
      this.elements.todayPomodoros.textContent =
        stats.today.workSessions.toString();
    }

    if (this.elements.todayFocusTime) {
      this.elements.todayFocusTime.textContent = this.formatDuration(
        stats.today.totalWorkTime
      );
    }

    if (this.elements.todayCompletedTasks) {
      this.elements.todayCompletedTasks.textContent =
        stats.today.completedTasks.toString();
    }
  }

