  // ==========================================================================
  // TOAST NOTIFICATIONS
  // ==========================================================================

  /**
   * Show toast notification
   */
  showToast(
    message: string,
    type: ToastType = 'info',
    duration: number = 3000
  ): void {
    const container = this.ensureToastContainer();

    const toast = document.createElement('div');
    const toastId = `toast-${++this.toastCounter}`;

    toast.className = `toast toast-${type}`;
    toast.id = toastId;
    toast.innerHTML = `
      <span class="toast-message">${this.escapeHtml(message)}</span>
      <button class="toast-close" aria-label="Close notification">
        <svg width="16" height="16" viewBox="0 0 16 16">
          <path d="M4.646 4.646a.5.5 0 01.708 0L8 7.293l2.646-2.647a.5.5 0 01.708.708L8.707 8l2.647 2.646a.5.5 0 01-.708.708L8 8.707l-2.646 2.647a.5.5 0 01-.708-.708L7.293 8 4.646 5.354a.5.5 0 010-.708z"/>
        </svg>
      </button>
    `;

    container.appendChild(toast);

    // Auto-remove after duration
    const timeoutId = setTimeout(() => {
      this.removeToast(toastId);
    }, duration);

    // Store reference
    this.activeToasts.set(toastId, toast);
    (toast as any)._timeoutId = timeoutId;

    // Add close button listener
    const closeBtn = toast.querySelector('.toast-close');
    closeBtn?.addEventListener('click', () => {
      this.removeToast(toastId);
    });

    // Animate in
    if (this.enableAnimations) {
      requestAnimationFrame(() => {
        toast.classList.add('active');
      });
    }
  }

  /**
   * Remove toast notification
   */
  private removeToast(toastId: string): void {
    const toast = this.activeToasts.get(toastId);
    if (!toast) return;

    // Clear timeout
    const timeoutId = (toast as any)._timeoutId;
    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    // Animate out
    if (this.enableAnimations) {
      toast.classList.remove('active');
      setTimeout(() => {
        toast.remove();
        this.activeToasts.delete(toastId);
      }, 300);
    } else {
      toast.remove();
      this.activeToasts.delete(toastId);
    }
  }

  /**
   * Ensure toast container exists
   */
  private ensureToastContainer(): HTMLElement {
    let container = this.elements.toastContainer;

    if (!container) {
      container = document.createElement('div');
      container.id = 'toast-container';
      container.className = 'toast-container';
      document.body.appendChild(container);
      this.elements.toastContainer = container;
    }

    return container;
  }

  // ==========================================================================
  // ELEMENT BINDING
  // ==========================================================================

  /**
   * Bind UI elements to event handlers
   */
  bindElements(): void {
    // Timer buttons
    this.elements.startButton?.addEventListener('click', () => {
      this.emit('timer:start');
    });

    this.elements.pauseButton?.addEventListener('click', () => {
      this.emit('timer:pause');
    });

    this.elements.resetButton?.addEventListener('click', () => {
      this.emit('timer:reset');
    });

    this.elements.skipButton?.addEventListener('click', () => {
      this.emit('timer:skip');
    });

    // Task form
    this.elements.taskForm?.addEventListener('submit', (e) => {
      e.preventDefault();
      this.handleTaskFormSubmit();
    });

    // Modal close
    this.elements.modalClose?.addEventListener('click', () => {
      this.elements.modalOverlay?.classList.remove('active');
    });

    this.elements.modalOverlay?.addEventListener('click', (e) => {
      if (e.target === this.elements.modalOverlay) {
        this.elements.modalOverlay.classList.remove('active');
      }
    });
  }

  /**
   * Handle task form submission
   */
  private async handleTaskFormSubmit(): Promise<void> {
    const input = this.elements.taskInput;
    if (!input || !input.value.trim()) return;

    try {
      await this.store.addTask({
        title: input.value.trim(),
        priority: TaskPriority.MEDIUM,
        status: TaskStatus.TODO,
        completedPomodoros: 0,
      });

      input.value = '';
      this.showToast('Task added', 'success');
    } catch (error) {
      this.showToast('Failed to add task', 'error');
    }
  }

  // ==========================================================================
  // THEME MANAGEMENT
  // ==========================================================================

  /**
   * Set theme
   */
  setTheme(theme: 'light' | 'dark'): void {
    this.currentTheme = theme;
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
  }

  /**
   * Get current theme
   */
  getTheme(): 'light' | 'dark' {
    return this.currentTheme;
  }

  /**
   * Toggle theme
   */
  toggleTheme(): void {
    this.setTheme(this.currentTheme === 'light' ? 'dark' : 'light');
  }

  // ==========================================================================
  // CUSTOM RENDERERS
  // ==========================================================================

  /**
   * Register custom task renderer
   */
  registerTaskRenderer(name: string, renderer: ComponentRenderFn<Task>): void {
    this.taskRenderers.set(name, renderer);
  }

  /**
   * Register custom statistics renderer
   */
  registerStatRenderer(name: string, renderer: ComponentRenderFn<any>): void {
    this.statRenderers.set(name, renderer);
  }

  // ==========================================================================
  // UTILITY METHODS
  // ==========================================================================

  /**
   * Format time as MM:SS
   */
  private formatTime(seconds: number): string {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  /**
   * Format duration in human-readable format
   */
  private formatDuration(seconds: number): string {
    const hours = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);

    if (hours > 0) {
      return `${hours}h ${mins}m`;
    }
    return `${mins}m`;
  }

  /**
   * Get state display text
   */
  private getStateText(state: TimerState): string {
    switch (state) {
      case TimerState.IDLE:
        return 'Ready';
      case TimerState.WORKING:
        return 'Focus Time';
      case TimerState.SHORT_BREAK:
        return 'Short Break';
      case TimerState.LONG_BREAK:
        return 'Long Break';
      case TimerState.PAUSED:
        return 'Paused';
      default:
        return '';
    }
  }

  /**
   * Get session type text
   */
  private getSessionTypeText(): string {
    const sessionType = this.store.getCurrentSessionType();
    const completedCount =
      this.store.getState().completedSessionsSinceLastLongBreak;
    const interval = this.store.getSettings().longBreakInterval;

    switch (sessionType) {
      case SessionType.WORK:
        return `Pomodoro ${completedCount + 1} of ${interval}`;
      case SessionType.SHORT_BREAK:
        return 'Short Break';
      case SessionType.LONG_BREAK:
        return 'Long Break';
      default:
        return '';
    }
  }

  /**
   * Get session duration
   */
  private getSessionDuration(sessionType: SessionType): number {
    const settings = this.store.getSettings();

    switch (sessionType) {
      case SessionType.WORK:
        return settings.workDuration;
      case SessionType.SHORT_BREAK:
        return settings.shortBreakDuration;
      case SessionType.LONG_BREAK:
        return settings.longBreakDuration;
    }
  }

  /**
   * Escape HTML to prevent XSS
   */
  private escapeHtml(text: string): string {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  /**
   * Animate list items
   */
  private animateListItems(container: HTMLElement): void {
    const items = container.querySelectorAll('.task-item');
    items.forEach((item, index) => {
      (item as HTMLElement).style.animationDelay = `${index * 50}ms`;
      item.classList.add('animate-in');
    });
  }

  /**
   * Emit custom event
   */
  private emit(eventName: string, detail?: any): void {
    const event = new CustomEvent(eventName, { detail });
    window.dispatchEvent(event);
  }

  // ==========================================================================
  // CLEANUP
  // ==========================================================================

  /**
   * Cleanup and destroy the controller
   */
  destroy(): void {
    // Unsubscribe from store
    if (this.unsubscribeStore) {
      this.unsubscribeStore();
    }

    // Clear all toasts
    this.activeToasts.forEach((_, id) => this.removeToast(id));

    // Clear renderers
    this.taskRenderers.clear();
    this.statRenderers.clear();
  }
}

/**
 * Default export
 */
export default UIController;

/**
 * Component Base Class - Lifecycle Management
 *
 * Provides automatic resource cleanup and memory leak prevention
 * for all components in the application.
 *
 * Features:
 * - Automatic event listener cleanup
 * - Timer (setTimeout/setInterval) tracking and cleanup
 * - AbortController for fetch requests
 * - DOM reference clearing
 * - Subscription management
 */

import { eventEmitter } from '../utils/EventEmitter';
import { EventType, EventListener } from '../types';

/**
 * Resource types that can be tracked
 */
type CleanupFunction = () => void;

/**
 * Base class for all components requiring lifecycle management
 */
export abstract class Component {
  /**
   * Array of cleanup functions to execute on destroy
   */
  protected cleanup: CleanupFunction[] = [];

  /**
   * Track if component has been destroyed
   */
  protected destroyed: boolean = false;

  /**
   * Track all timer IDs for cleanup
   */
  private timers: Set<number> = new Set();

  /**
   * Track all event listeners for automatic removal
   * Format: { element, event, handler, options }
   */
  private eventListeners: Array<{
    element: HTMLElement | Document | Window;
    event: string;
    handler: EventListener;
    options?: AddEventListenerOptions;
  }> = [];

  /**
   * Track event emitter subscriptions
   */
  private eventSubscriptions: Array<{
    event: EventType;
    listener: EventListener;
  }> = [];

  /**
   * Track AbortControllers for fetch requests
   */
  private abortControllers: Set<AbortController> = new Set();

  /**
   * Constructor - Subclasses should call super() if they override
   */
  constructor() {
    // Setup automatic cleanup on page unload
    this.addAutoCleanup(() => {
      this.destroyed = true;
    });
  }

  // ==========================================================================
  // PUBLIC LIFECYCLE METHODS
  // ==========================================================================

  /**
   * Destroy the component and clean up all resources
   * This should be called when the component is no longer needed
   */
  public destroy(): void {
    if (this.destroyed) {
      console.warn(
        `[Component] Attempted to destroy already destroyed component`
      );
      return;
    }

    // Run all cleanup functions in reverse order
    for (let i = this.cleanup.length - 1; i >= 0; i--) {
      try {
        this.cleanup[i]();
      } catch (error) {
        console.error('[Component] Error during cleanup:', error);
      }
    }

    // Clear all tracking collections
    this.cleanup = [];
    this.timers.clear();
    this.eventListeners = [];
    this.eventSubscriptions = [];
    this.abortControllers.clear();

    this.destroyed = true;
  }

  /**
   * Check if component has been destroyed
   */
  public isDestroyed(): boolean {
    return this.destroyed;
  }

  // ==========================================================================
  // RESOURCE MANAGEMENT - TIMERS
  // ==========================================================================

  /**
   * Wrapper for setTimeout that automatically tracks and cleans up the timer
   */
  protected setTimeout(handler: () => void, timeout: number): number {
    if (this.destroyed) {
      console.warn('[Component] Cannot set timeout on destroyed component');
      return -1;
    }

    const timerId = window.setTimeout(() => {
      this.timers.delete(timerId);
      handler();
    }, timeout);

    this.timers.add(timerId);
    return timerId;
  }

  /**
   * Wrapper for setInterval that automatically tracks and cleans up the timer
   */
  protected setInterval(handler: () => void, interval: number): number {
    if (this.destroyed) {
      console.warn('[Component] Cannot set interval on destroyed component');
      return -1;
    }

    const timerId = window.setInterval(handler, interval);
    this.timers.add(timerId);

    return timerId;
  }

  /**
   * Clear a specific timer
   */
  protected clearTimeout(timerId: number): void {
    window.clearTimeout(timerId);
    this.timers.delete(timerId);
  }

  /**
   * Clear a specific interval
   */
  protected clearInterval(timerId: number): void {
    window.clearInterval(timerId);
    this.timers.delete(timerId);
  }

  /**
   * Clear all tracked timers
   */
  protected clearAllTimers(): void {
    this.timers.forEach((timerId) => {
      window.clearTimeout(timerId);
      window.clearInterval(timerId);
    });
    this.timers.clear();
  }

  // ==========================================================================
  // RESOURCE MANAGEMENT - DOM EVENT LISTENERS
  // ==========================================================================

  /**
   * Wrapper for addEventListener that automatically tracks and removes the listener
   */
  protected addEventListener(
    element: HTMLElement | Document | Window,
    event: string,
    handler: EventListener,
    options?: AddEventListenerOptions
  ): void {
    if (this.destroyed) {
      console.warn(
        '[Component] Cannot add event listener to destroyed component'
      );
      return;
    }

    element.addEventListener(event, handler as EventListener, options);
    this.eventListeners.push({
      element,
      event,
      handler: handler as EventListener,
      options,
    });
  }

  /**
   * Remove a specific tracked event listener
   */
  protected removeEventListener(
    element: HTMLElement | Document | Window,
    event: string,
    handler: EventListener
  ): void {
    element.removeEventListener(event, handler);
    this.eventListeners = this.eventListeners.filter(
      (el) =>
        !(
          el.element === element &&
          el.event === event &&
          el.handler === handler
        )
    );
  }

  /**
   * Remove all tracked event listeners
   */
  protected removeAllEventListeners(): void {
    this.eventListeners.forEach(({ element, event, handler, options }) => {
      element.removeEventListener(event, handler, options);
    });
    this.eventListeners = [];
  }

  // ==========================================================================
  // RESOURCE MANAGEMENT - EVENT EMITTER SUBSCRIPTIONS
  // ==========================================================================

  /**
   * Subscribe to an event emitter with automatic cleanup
   */
  protected subscribeEvent(event: EventType, listener: EventListener): void {
    if (this.destroyed) {
      console.warn(
        '[Component] Cannot subscribe to event on destroyed component'
      );
      return;
    }

    eventEmitter.on(event, listener);
    this.eventSubscriptions.push({ event, listener });
  }

  /**
   * Unsubscribe from a specific event
   */
  protected unsubscribeEvent(event: EventType, listener: EventListener): void {
    eventEmitter.off(event, listener);
    this.eventSubscriptions = this.eventSubscriptions.filter(
      (sub) => !(sub.event === event && sub.listener === listener)
    );
  }

  /**
   * Unsubscribe from all tracked events
   */
  protected unsubscribeAllEvents(): void {
    this.eventSubscriptions.forEach(({ event, listener }) => {
      eventEmitter.off(event, listener);
    });
    this.eventSubscriptions = [];
  }

  // ==========================================================================
  // RESOURCE MANAGEMENT - FETCH REQUESTS
  // ==========================================================================

  /**
   * Create an AbortController for fetch requests
   */
  protected createAbortController(): AbortController {
    if (this.destroyed) {
      console.warn(
        '[Component] Cannot create abort controller for destroyed component'
      );
      throw new Error('Cannot create abort controller for destroyed component');
    }

    const controller = new AbortController();
    this.abortControllers.add(controller);

    return controller;
  }

  /**
   * Abort all tracked fetch requests
   */
  protected abortAllRequests(): void {
    this.abortControllers.forEach((controller) => {
      controller.abort();
    });
    this.abortControllers.clear();
  }

  // ==========================================================================
  // GENERAL RESOURCE MANAGEMENT
  // ==========================================================================

  /**
   * Register a custom cleanup function
   */
  protected addAutoCleanup(cleanupFn: CleanupFunction): void {
    if (this.destroyed) {
      console.warn('[Component] Cannot add cleanup to destroyed component');
      return;
    }

    this.cleanup.push(cleanupFn);
  }

  /**
   * Create a cleanup function that will run a callback once on destroy
   */
  protected registerCleanup(callback: CleanupFunction): void {
    this.addAutoCleanup(() => {
      try {
        callback();
      } catch (error) {
        console.error('[Component] Error in registered cleanup:', error);
      }
    });
  }

  // ==========================================================================
  // HELPER METHODS
  // ==========================================================================

  /**
   * Safely execute a function only if component is not destroyed
   */
  protected safeExecute(fn: () => void): void {
    if (!this.destroyed) {
      fn();
    }
  }

  /**
   * Log a warning if operation is attempted on destroyed component
   */
  protected warnIfDestroyed(operation: string): void {
    if (this.destroyed) {
      console.warn(`[Component] Cannot ${operation}: component is destroyed`);
    }
  }
}

/**
 * Factory function to create a component with automatic cleanup
 */
export function createComponent<T extends Component>(
  ComponentClass: new (...args: any[]) => T,
  ...args: any[]
): T {
  return new ComponentClass(...args);
}

export default Component;

/**
 * Main Entry Point
 *
 * Application bootstrap and initialization
 */

import { createApp, destroyApp, setApp } from './App';
import './styles/main.css';

// ============================================================================
// APPLICATION CONFIGURATION
// ============================================================================

const APP_CONFIG = {
  // Enable debug mode in development
  debug: import.meta.env.DEV ?? true,

  // Storage type (local for localStorage, memory for in-memory)
  storageType: 'local' as const,

  // Auto-save configuration
  autoSave: true,
  autoSaveDebounceMs: 2000,

  // Enable keyboard shortcuts
  enableKeyboardShortcuts: true,

  // Enable notifications
  enableNotifications: true,
};

// ============================================================================
// GLOBAL APP INSTANCE
// ============================================================================

let appInstance: Awaited<ReturnType<typeof createApp>> | null = null;

// ============================================================================
// INITIALIZATION
// ============================================================================

/**
 * Initialize the application
 */
async function initApp(): Promise<void> {
  try {
    console.log('Pomodoro Todo App - Initializing...');

    // Create and initialize app
    appInstance = await createApp(APP_CONFIG);

    // Set as global instance
    setApp(appInstance);

    console.log('Pomodoro Todo App - Ready!');

    // Emit app ready event
    window.dispatchEvent(new CustomEvent('app:ready'));
  } catch (error) {
    console.error('Failed to initialize app:', error);

    // Show error to user
    showInitError(error instanceof Error ? error.message : String(error));
  }
}

/**
 * Show initialization error
 */
function showInitError(message: string): void {
  const root = document.getElementById('app');
  if (!root) return;

  root.innerHTML = `
    <div class="init-error">
      <div class="init-error-content">
        <h2>Initialization Failed</h2>
        <p>${escapeHtml(message)}</p>
        <button onclick="location.reload()">Try Again</button>
      </div>
    </div>
  `;
}

/**
 * Escape HTML to prevent XSS
 */
function escapeHtml(text: string): string {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ============================================================================
// LIFECYCLE HANDLERS
// ============================================================================

/**
 * Handle page visibility changes
 */
function handleVisibilityChange(): void {
  if (document.hidden) {
    console.log('App hidden - pausing non-essential operations');
  } else {
    console.log('App visible - resuming operations');
  }
}

/**
 * Handle beforeunload
 */
function handleBeforeUnload(e: BeforeUnloadEvent): void {
  // Cancel any ongoing operations
  console.log('App unloading...');

  // Note: Modern browsers ignore custom messages
  // but we still return a string for older browsers
  const hasUnsavedWork = appInstance?.getStore().getTimerState() !== 'idle';

  if (hasUnsavedWork) {
    e.preventDefault();
    e.returnValue = '';
  }
}

/**
 * Handle online/offline status
 */
function handleOnlineStatus(): void {
  if (navigator.onLine) {
    console.log('App back online');
    document.body.classList.remove('offline');
  } else {
    console.log('App went offline');
    document.body.classList.add('offline');
  }
}

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Global error handler
 */
window.addEventListener('error', (event) => {
  console.error('Global error:', event.error);
});

/**
 * Global unhandled promise rejection handler
 */
window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled promise rejection:', event.reason);
});

// ============================================================================
// DOM READY
// ============================================================================

/**
 * Check if DOM is ready
 */
function isDomReady(): boolean {
  return (
    document.readyState === 'complete' || document.readyState === 'interactive'
  );
}

/**
 * Initialize when DOM is ready
 */
function onDomReady(): void {
  // Setup lifecycle handlers
  document.addEventListener('visibilitychange', handleVisibilityChange);
  window.addEventListener('beforeunload', handleBeforeUnload);
  window.addEventListener('online', handleOnlineStatus);
  window.addEventListener('offline', handleOnlineStatus);

  // Check initial online status
  handleOnlineStatus();

  // Initialize app
  initApp();
}

// ============================================================================
// BOOTSTRAP
// ============================================================================

if (isDomReady()) {
  // DOM already ready
  onDomReady();
} else {
  // Wait for DOM to be ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', onDomReady);
  } else {
    // Fallback: use timeout
    setTimeout(onDomReady, 0);
  }
}

// ============================================================================
// HOT MODULE REPLACEMENT (DEV ONLY)
// ============================================================================

if (import.meta.hot) {
  import.meta.hot.accept(async () => {
    console.log('HMR: Reloading app...');

    // Destroy current app
    if (appInstance) {
      appInstance.destroy();
      appInstance = null;
    }

    // Reinitialize
    await initApp();
  });
}

// ============================================================================
// EXPORTS FOR EXTERNAL USE
// ============================================================================

export { initApp, destroyApp };
export type { AppConfig } from './App';

// Also export as global for debugging
if (APP_CONFIG.debug) {
  (window as any).app = {
    init: initApp,
    destroy: () => {
      if (appInstance) {
        appInstance.destroy();
        appInstance = null;
      }
    },
    getInstance: () => appInstance,
    getStore: () => appInstance?.getStore(),
    getTimer: () => appInstance?.getTimerController(),
    getUI: () => appInstance?.getUIController(),
    getKeyboard: () => appInstance?.getKeyboardManager(),
  };
  console.log('Debug mode: app available at window.app');
}

/**
 * Audio Manager for Pomodoro Timer
 * Handles all audio feedback for timer events
 */

import { AudioEventType } from '../types';

/**
 * Audio configuration for different notification types
 */
interface AudioConfig {
  src: string;
  volume: number;
  loop?: boolean;
}

/**
 * Sound effect types
 */
export enum SoundType {
  START = 'start',
  COMPLETE = 'complete',
  BREAK_START = 'break_start',
  PAUSE = 'pause',
  TICK = 'tick',
}

/**
 * Default sound URLs (can be overridden)
 */
const DEFAULT_SOUNDS: Record<SoundType, string> = {
  [SoundType.START]: '/sounds/start.mp3',
  [SoundType.COMPLETE]: '/sounds/complete.mp3',
  [SoundType.BREAK_START]: '/sounds/break.mp3',
  [SoundType.PAUSE]: '/sounds/pause.mp3',
  [SoundType.TICK]: '/sounds/tick.mp3',
};

/**
 * Audio load state
 */
enum AudioLoadState {
  IDLE = 'idle',
  LOADING = 'loading',
  LOADED = 'loaded',
  ERROR = 'error',
}

/**
 * Audio element wrapper with load state
 */
interface AudioElement {
  element: HTMLAudioElement;
  state: AudioLoadState;
  config: AudioConfig;
}

/**
 * AudioManager class for handling all timer-related audio feedback
 * Supports preloading, volume control, and muting
 */
export class AudioManager {
  private audioElements: Map<SoundType, AudioElement>;
  private masterVolume: number;
  private isMuted: boolean;
  private isBrowserSupported: boolean;
  private audioContext: AudioContext | null;

  constructor() {
    this.audioElements = new Map();
    this.masterVolume = 0.7;
    this.isMuted = false;
    this.isBrowserSupported = this.checkBrowserSupport();
    this.audioContext = this.initAudioContext();

    // Preload default sounds
    this.preloadSounds();
  }

  /**
   * Check if browser supports HTML5 Audio
   */
  private checkBrowserSupport(): boolean {
    return typeof Audio !== 'undefined';
  }

  /**
   * Initialize Web Audio API for advanced features
   */
  private initAudioContext(): AudioContext | null {
    try {
      const AudioContextClass =
        window.AudioContext || (window as any).webkitAudioContext;
      return AudioContextClass ? new AudioContextClass() : null;
    } catch {
      return null;
    }
  }

  /**
   * Preload all default sounds
   */
  private preloadSounds(): void {
    if (!this.isBrowserSupported) {
      return;
    }

    Object.values(SoundType).forEach((soundType) => {
      this.loadSound(soundType, DEFAULT_SOUNDS[soundType]);
    });
  }

  /**
   * Load a sound file
   * @param soundType - Type of sound to load
   * @param src - URL to the sound file
   */
  public loadSound(soundType: SoundType, src: string): void {
    if (!this.isBrowserSupported) {
      return;
    }

    // Unload existing sound if present
    const existing = this.audioElements.get(soundType);
    if (existing) {
      existing.element.pause();
      existing.element.src = '';
    }

    const audio = new Audio(src);
    audio.preload = 'auto';
    audio.volume = this.getEffectiveVolume();

    const audioElement: AudioElement = {
      element: audio,
      state: AudioLoadState.LOADING,
      config: { src, volume: this.masterVolume },
    };

    audio.addEventListener(
      'canplaythrough',
      () => {
        audioElement.state = AudioLoadState.LOADED;
      },
      { once: true }
    );

    audio.addEventListener(
      'error',
      () => {
        audioElement.state = AudioLoadState.ERROR;
        console.warn(`Failed to load audio: ${src}`);
      },
      { once: true }
    );

    this.audioElements.set(soundType, audioElement);
  }

  /**
   * Play a sound by type
   * @param soundType - Type of sound to play
   * @param volume - Optional volume override (0-1)
   */
  public play(soundType: SoundType, volume?: number): void {
    if (!this.isBrowserSupported || this.isMuted) {
      return;
    }

    // Resume AudioContext if suspended (required by some browsers)
    if (this.audioContext?.state === 'suspended') {
      this.audioContext.resume().catch(() => {
        // Ignore resume errors
      });
    }

    const audioWrapper = this.audioElements.get(soundType);

    if (!audioWrapper || audioWrapper.state === AudioLoadState.ERROR) {
      return;
    }

    const audio = audioWrapper.element;
    audio.volume =
      volume !== undefined
        ? volume * this.masterVolume
        : this.getEffectiveVolume();

    // Reset to beginning if already playing
    audio.currentTime = 0;

    const playPromise = audio.play();

    if (playPromise !== undefined) {
      playPromise.catch((error) => {
        // Auto-play was prevented, log for debugging
        console.debug('Audio playback prevented:', error);
      });
    }
  }

  /**
   * Play sound when timer starts
   */
  public playStartSound(): void {
    this.play(SoundType.START);
  }

  /**
   * Play sound when timer completes
   */
  public playCompleteSound(): void {
    this.play(SoundType.COMPLETE);
  }

  /**
   * Play sound when break starts
   */
  public playBreakStartSound(): void {
    this.play(SoundType.BREAK_START);
  }

  /**
   * Play sound when timer is paused
   */
  public playPauseSound(): void {
    this.play(SoundType.PAUSE);
  }

  /**
   * Play tick sound (for optional ticking)
   */
  public playTickSound(): void {
    this.play(SoundType.TICK, 0.3); // Lower volume for tick
  }

  /**
   * Set master volume
   * @param volume - Volume level between 0 and 1
   */
  public setVolume(volume: number): void {
    this.masterVolume = Math.max(0, Math.min(1, volume));

    // Update all loaded audio elements
    this.audioElements.forEach((wrapper) => {
      wrapper.element.volume = this.getEffectiveVolume();
      wrapper.config.volume = this.masterVolume;
    });
  }

  /**
   * Get current master volume
   */
  public getVolume(): number {
    return this.masterVolume;
  }

  /**
   * Mute all sounds
   */
  public mute(): void {
    this.isMuted = true;

    this.audioElements.forEach((wrapper) => {
      wrapper.element.volume = 0;
    });
  }

  /**
   * Unmute sounds
   */
  public unmute(): void {
    this.isMuted = false;

    this.audioElements.forEach((wrapper) => {
      wrapper.element.volume = this.getEffectiveVolume();
    });
  }

  /**
   * Toggle mute state
   */
  public toggleMute(): void {
    if (this.isMuted) {
      this.unmute();
    } else {
      this.mute();
    }
  }

  /**
   * Check if currently muted
   */
  public isMutedState(): boolean {
    return this.isMuted;
  }

  /**
   * Get effective volume considering mute state
   */
  private getEffectiveVolume(): number {
    return this.isMuted ? 0 : this.masterVolume;
  }

  /**
   * Stop all currently playing sounds
   */
  public stopAll(): void {
    this.audioElements.forEach((wrapper) => {
      if (!wrapper.element.paused) {
        wrapper.element.pause();
        wrapper.element.currentTime = 0;
      }
    });
  }

  /**
   * Stop a specific sound
   */
  public stop(soundType: SoundType): void {
    const wrapper = this.audioElements.get(soundType);
    if (wrapper) {
      wrapper.element.pause();
      wrapper.element.currentTime = 0;
    }
  }

  /**
   * Check if browser audio is supported
   */
  public isAudioSupported(): boolean {
    return this.isBrowserSupported;
  }

  /**
   * Check if a specific sound is loaded
   */
  public isSoundLoaded(soundType: SoundType): boolean {
    const wrapper = this.audioElements.get(soundType);
    return wrapper?.state === AudioLoadState.LOADED || false;
  }

  /**
   * Set custom sound URL for a sound type
   * @param soundType - Type of sound to customize
   * @param url - URL to the custom sound file
   */
  public setCustomSound(soundType: SoundType, url: string): void {
    this.loadSound(soundType, url);
  }

  /**
   * Play audio event based on timer event type
   */
  public playForEvent(eventType: AudioEventType): void {
    switch (eventType) {
      case AudioEventType.START:
        this.playStartSound();
        break;
      case AudioEventType.COMPLETE:
        this.playCompleteSound();
        break;
      case AudioEventType.BREAK_START:
        this.playBreakStartSound();
        break;
      case AudioEventType.PAUSE:
        this.playPauseSound();
        break;
    }
  }

  /**
   * Cleanup and release resources
   */
  public dispose(): void {
    this.stopAll();
    this.audioElements.forEach((wrapper) => {
      wrapper.element.src = '';
      wrapper.element.load();
    });
    this.audioElements.clear();

    if (this.audioContext) {
      this.audioContext.close().catch(() => {
        // Ignore close errors
      });
      this.audioContext = null;
    }
  }

  /**
   * Generate a simple beep tone using Web Audio API
   * Useful as fallback when sound files fail to load
   * @param frequency - Frequency in Hz
   * @param duration - Duration in seconds
   */
  public playBeep(frequency: number = 800, duration: number = 0.1): void {
    if (!this.audioContext || this.isMuted) {
      return;
    }

    try {
      const oscillator = this.audioContext.createOscillator();
      const gainNode = this.audioContext.createGain();

      oscillator.connect(gainNode);
      gainNode.connect(this.audioContext.destination);

      oscillator.frequency.value = frequency;
      oscillator.type = 'sine';

      gainNode.gain.setValueAtTime(
        this.masterVolume,
        this.audioContext.currentTime
      );
      gainNode.gain.exponentialRampToValueAtTime(
        0.01,
        this.audioContext.currentTime + duration
      );

      oscillator.start(this.audioContext.currentTime);
      oscillator.stop(this.audioContext.currentTime + duration);
    } catch (error) {
      console.debug('Web Audio API beep failed:', error);
    }
  }

  /**
   * Play a sequence of beeps
   * @param pattern - Array of [frequency, duration] pairs
   * @param interval - Delay between beeps in ms
   */
  public playBeepSequence(
    pattern: Array<[number, number]>,
    interval: number = 100
  ): void {
    if (!this.audioContext || this.isMuted) {
      return;
    }

    pattern.forEach(([frequency, duration], index) => {
      setTimeout(
        () => {
          this.playBeep(frequency, duration);
        },
        index * (duration * 1000 + interval)
      );
    });
  }
}

/**
 * Singleton instance for global use
 */
let audioManagerInstance: AudioManager | null = null;

/**
 * Get or create the singleton AudioManager instance
 */
export function getAudioManager(): AudioManager {
  if (!audioManagerInstance) {
    audioManagerInstance = new AudioManager();
  }
  return audioManagerInstance;
}

/**
 * Reset the singleton instance (useful for testing)
 */
export function resetAudioManager(): void {
  if (audioManagerInstance) {
    audioManagerInstance.dispose();
  }
  audioManagerInstance = null;
}

/**
 * Error Handler Service
 *
 * Centralized error handling system for the application.
 * Provides error logging, user notification, error recovery, and reporting.
 *
 * Features:
 * - Structured error logging with context
 * - User-friendly error messages
 * - Error recovery mechanisms
 * - Error reporting (extensible for monitoring services)
 * - Error categorization and routing
 */

// ============================================================================
// ERROR TYPE DEFINITIONS
// ============================================================================

/**
 * Error severity levels
 */
export enum ErrorSeverity {
  LOW = 'low', // Non-critical, can be ignored
  MEDIUM = 'medium', // Affects some functionality
  HIGH = 'high', // Major functionality affected
  CRITICAL = 'critical', // Application unusable
}

/**
 * Error categories
 */
export enum ErrorCategory {
  STORAGE = 'storage', // Storage-related errors
  NETWORK = 'network', // Network/API errors
  TIMER = 'timer', // Timer functionality errors
  VALIDATION = 'validation', // Input validation errors
  UI = 'ui', // UI/rendering errors
  INITIALIZATION = 'initialization', // App initialization errors
  PERMISSION = 'permission', // Permission-related errors
  UNKNOWN = 'unknown', // Uncategorized errors
}

/**
 * Error context information
 */
export interface ErrorContext {
  component?: string; // Component where error occurred
  action?: string; // Action being performed
  timestamp?: number; // When error occurred
  userId?: string; // User ID (if applicable)
  sessionId?: string; // Session ID
  additionalData?: Record<string, any>; // Any additional context
}

/**
 * Error log entry
 */
export interface ErrorLog {
  id: string; // Unique error ID
  message: string; // User-friendly message
  technicalMessage: string; // Technical error message
  category: ErrorCategory; // Error category
  severity: ErrorSeverity; // Error severity
  stack?: string; // Stack trace
  context: ErrorContext; // Error context
  timestamp: number; // Timestamp
  recovered: boolean; // Whether error was recovered
  reported: boolean; // Whether error was reported
}

/**
 * Recovery action definition
 */
export interface RecoveryAction {
  label: string; // Button text
  action: () => void | Promise<void>; // Recovery function
  primary?: boolean; // Is primary action
}

/**
 * Error handler configuration
 */
export interface ErrorHandlerConfig {
  enableLogging: boolean; // Enable error logging
  enableReporting: boolean; // Enable error reporting
  enableNotifications: boolean; // Enable user notifications
  maxLogSize: number; // Maximum error logs to keep
  autoRecovery: boolean; // Enable automatic recovery attempts
  reportUrl?: string; // URL for error reporting endpoint
}

// ============================================================================
// CUSTOM ERROR CLASSES
// ============================================================================

/**
 * Base application error
 */
export class AppError extends Error {
  constructor(
    message: string,
    public category: ErrorCategory,
    public severity: ErrorSeverity = ErrorSeverity.MEDIUM,
    public recoverable: boolean = true,
    public originalError?: Error
  ) {
    super(message);
    this.name = 'AppError';
    Error.captureStackTrace?.(this, AppError);
  }
}

/**
 * Storage-related errors
 */
export class StorageCriticalError extends AppError {
  constructor(message: string, originalError?: Error) {
    super(
      message,
      ErrorCategory.STORAGE,
      ErrorSeverity.HIGH,
      false,
      originalError
    );
    this.name = 'StorageCriticalError';
  }
}

export class StorageRecoverableError extends AppError {
  constructor(message: string, originalError?: Error) {
    super(
      message,
      ErrorCategory.STORAGE,
      ErrorSeverity.LOW,
      true,
      originalError
    );
    this.name = 'StorageRecoverableError';
  }
}

/**
 * Timer-related errors
 */
export class TimerError extends AppError {
  constructor(message: string, originalError?: Error) {
    super(
      message,
      ErrorCategory.TIMER,
      ErrorSeverity.MEDIUM,
      true,
      originalError
    );
    this.name = 'TimerError';
  }
}

/**
 * Validation errors
 */
export class ValidationError extends AppError {
  constructor(
    message: string,
    public field?: string
  ) {
    super(message, ErrorCategory.VALIDATION, ErrorSeverity.LOW, true);
    this.name = 'ValidationError';
  }
}

/**
 * Network errors
 */
export class NetworkError extends AppError {
  constructor(message: string, originalError?: Error) {
    super(
      message,
      ErrorCategory.NETWORK,
      ErrorSeverity.MEDIUM,
      true,
      originalError
    );
    this.name = 'NetworkError';
  }
}

/**
 * Permission errors
 */
export class PermissionError extends AppError {
  constructor(
    message: string,
    public permissionType: string
  ) {
    super(message, ErrorCategory.PERMISSION, ErrorSeverity.MEDIUM, false);
    this.name = 'PermissionError';
  }
}

// ============================================================================
// ERROR HANDLER SERVICE
// ============================================================================

/**
 * Error Handler Service
 *
 * Central service for handling all application errors
 */
class ErrorHandlerService {
  private config: ErrorHandlerConfig;
  private errorLogs: ErrorLog[] = [];
  private errorCallbacks: Array<(error: ErrorLog) => void> = [];
  private recoveryStrategies: Map<ErrorCategory, RecoveryAction[]> = new Map();

  constructor(config: Partial<ErrorHandlerConfig> = {}) {
    this.config = {
      enableLogging: true,
      enableReporting: false,
      enableNotifications: true,
      maxLogSize: 100,
      autoRecovery: true,
      ...config,
    };

    this.initializeRecoveryStrategies();
  }

  /**
   * Initialize recovery strategies for different error categories
   */
  private initializeRecoveryStrategies(): void {
    // Storage recovery strategies
    this.recoveryStrategies.set(ErrorCategory.STORAGE, [
      {
        label: 'Retry',
        action: async () => {
          // Default retry logic
          window.location.reload();
        },
        primary: true,
      },
      {
        label: 'Clear Data',
        action: () => {
          if (confirm('This will clear all local data. Continue?')) {
            localStorage.clear();
            indexedDB.deleteDatabase('pomodoro-db');
            window.location.reload();
          }
        },
      },
    ]);

    // Timer recovery strategies
    this.recoveryStrategies.set(ErrorCategory.TIMER, [
      {
        label: 'Reset Timer',
        action: () => {
          window.dispatchEvent(new CustomEvent('timer:reset'));
        },
        primary: true,
      },
      {
        label: 'Skip Session',
        action: () => {
          window.dispatchEvent(new CustomEvent('timer:skip'));
        },
      },
    ]);

    // Permission recovery strategies
    this.recoveryStrategies.set(ErrorCategory.PERMISSION, [
      {
        label: 'Request Permission',
        action: async () => {
          // Trigger permission request
          window.dispatchEvent(new CustomEvent('permission:request'));
        },
        primary: true,
      },
    ]);

    // Network recovery strategies
    this.recoveryStrategies.set(ErrorCategory.NETWORK, [
      {
        label: 'Retry',
        action: async () => {
          window.location.reload();
        },
        primary: true,
      },
      {
        label: 'Work Offline',
        action: () => {
          // Enable offline mode
          window.dispatchEvent(new CustomEvent('app:offline'));
        },
      },
    ]);
  }

  /**
   * Handle an error
   */
  handleError(
    error: Error | AppError | unknown,
    context: ErrorContext = {}
  ): ErrorLog {
    // Normalize error
    const normalizedError = this.normalizeError(error);
    const appError = normalizedError as AppError;

    // Create error log
    const errorLog: ErrorLog = {
      id: this.generateErrorId(),
      message: this.getUserFriendlyMessage(appError),
      technicalMessage: appError.message,
      category: appError.category || ErrorCategory.UNKNOWN,
      severity: appError.severity || ErrorSeverity.MEDIUM,
      stack: appError.stack,
      context: {
        ...context,
        timestamp: context.timestamp || Date.now(),
      },
      timestamp: Date.now(),
      recovered: false,
      reported: false,
    };

    // Log error
    if (this.config.enableLogging) {
      this.logError(errorLog);
    }

    // Show user notification
    if (this.config.enableNotifications) {
      this.showErrorNotification(errorLog);
    }

    // Report error
    if (this.config.enableReporting) {
      this.reportError(errorLog);
    }

    // Store error log
    this.addErrorLog(errorLog);

    // Notify callbacks
    this.notifyCallbacks(errorLog);

    // Attempt recovery
    if (this.config.autoRecovery && appError.recoverable !== false) {
      this.attemptRecovery(errorLog);
    }

    return errorLog;
  }

  /**
   * Handle async error (Promise rejection)
   */
  handleAsyncError(error: unknown, context: ErrorContext = {}): ErrorLog {
    return this.handleError(error, {
      ...context,
      action: context.action || 'async_operation',
    });
  }

  /**
   * Normalize error to AppError
   */
  private normalizeError(error: unknown): AppError {
    if (error instanceof AppError) {
      return error;
    }

    if (error instanceof Error) {
      // Categorize standard errors
      const message = error.message.toLowerCase();

      // Storage errors
      if (
        message.includes('storage') ||
        message.includes('quota') ||
        message.includes('indexeddb')
      ) {
        if (message.includes('quota')) {
          return new StorageCriticalError('Storage space full', error);
        }
        return new StorageRecoverableError('Storage operation failed', error);
      }

      // Network errors
      if (message.includes('network') || message.includes('fetch')) {
        return new NetworkError('Network request failed', error);
      }

      // Permission errors
      if (message.includes('permission')) {
        return new PermissionError('Permission denied', 'unknown');
      }

      // Generic error
      return new AppError(
        error.message,
        ErrorCategory.UNKNOWN,
        ErrorSeverity.MEDIUM,
        true,
        error
      );
    }

    // Handle non-error objects
    const message = String(error);
    return new AppError(
      message || 'Unknown error occurred',
      ErrorCategory.UNKNOWN,
      ErrorSeverity.MEDIUM
    );
  }

  /**
   * Get user-friendly error message
   */
  private getUserFriendlyMessage(error: AppError): string {
    const friendlyMessages: Record<ErrorCategory, string> = {
      [ErrorCategory.STORAGE]:
        'Unable to save your data. Your changes may be lost.',
      [ErrorCategory.NETWORK]:
        'Unable to connect. Please check your internet connection.',
      [ErrorCategory.TIMER]: 'Timer encountered an issue. Please try again.',
      [ErrorCategory.VALIDATION]: 'Please check your input and try again.',
      [ErrorCategory.UI]: 'Display error. Please refresh the page.',
      [ErrorCategory.INITIALIZATION]:
        'Failed to start the application. Please refresh.',
      [ErrorCategory.PERMISSION]:
        'You need to grant permission for this feature.',
      [ErrorCategory.UNKNOWN]: 'Something went wrong. Please try again.',
    };

    return friendlyMessages[error.category] || error.message;
  }

  /**
   * Log error to console
   */
  private logError(errorLog: ErrorLog): void {
    const logMethod = this.getLogLevel(errorLog.severity);
    const logMessage = `[${errorLog.category.toUpperCase()}] ${errorLog.technicalMessage}`;

    console[logMethod](logMessage, {
      id: errorLog.id,
      context: errorLog.context,
      stack: errorLog.stack,
    });
  }

  /**
   * Get console log method based on severity
   */
  private getLogLevel(severity: ErrorSeverity): 'log' | 'warn' | 'error' {
    switch (severity) {
      case ErrorSeverity.LOW:
        return 'log';
      case ErrorSeverity.MEDIUM:
        return 'warn';
      case ErrorSeverity.HIGH:
      case ErrorSeverity.CRITICAL:
        return 'error';
      default:
        return 'error';
    }
  }

  /**
   * Show error notification to user
   */
  private showErrorNotification(errorLog: ErrorLog): void {
    // Dispatch custom event for UI components to listen
    window.dispatchEvent(
      new CustomEvent('error:occurred', {
        detail: {
          error: errorLog,
          recoveryActions: this.getRecoveryActions(errorLog.category),
        },
      })
    );
  }

  /**
   * Report error to monitoring service
   */
  private reportError(errorLog: ErrorLog): void {
    if (!this.config.reportUrl) return;

    // In a real implementation, send to monitoring service
    // Example: Sentry, LogRocket, custom endpoint
    fetch(this.config.reportUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(errorLog),
    }).catch(() => {
      // Silently fail - don't create infinite error loop
    });

    errorLog.reported = true;
  }

  /**
   * Add error to logs
   */
  private addErrorLog(errorLog: ErrorLog): void {
    this.errorLogs.push(errorLog);

    // Keep only recent errors
    if (this.errorLogs.length > this.config.maxLogSize) {
      this.errorLogs.shift();
    }

    // Persist to localStorage for debugging
    try {
      const recentLogs = this.errorLogs.slice(-10); // Keep last 10
      localStorage.setItem('pomodoro_error_logs', JSON.stringify(recentLogs));
    } catch {
      // Ignore storage errors
    }
  }

  /**
   * Get recovery actions for error category
   */
  private getRecoveryActions(category: ErrorCategory): RecoveryAction[] {
    return this.recoveryStrategies.get(category) || [];
  }

  /**
   * Attempt automatic error recovery
   */
  private attemptRecovery(errorLog: ErrorLog): void {
    const actions = this.getRecoveryActions(errorLog.category);

    // For auto-recovery, only use primary action
    const primaryAction = actions.find((a) => a.primary);

    if (primaryAction) {
      try {
        primaryAction.action();
        errorLog.recovered = true;
      } catch (error) {
        // Recovery failed - log but don't crash
        console.error('Recovery failed:', error);
      }
    }
  }

  /**
   * Notify all error callbacks
   */
  private notifyCallbacks(errorLog: ErrorLog): void {
    this.errorCallbacks.forEach((callback) => {
      try {
        callback(errorLog);
      } catch {
        // Don't let callback errors propagate
      }
    });
  }

  /**
   * Generate unique error ID
   */
  private generateErrorId(): string {
    return `err_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Register error callback
   */
  onError(callback: (error: ErrorLog) => void): () => void {
    this.errorCallbacks.push(callback);

    // Return unsubscribe function
    return () => {
      const index = this.errorCallbacks.indexOf(callback);
      if (index > -1) {
        this.errorCallbacks.splice(index, 1);
      }
    };
  }

  /**
   * Get recent error logs
   */
  getErrorLogs(limit?: number): ErrorLog[] {
    if (limit) {
      return this.errorLogs.slice(-limit);
    }
    return [...this.errorLogs];
  }

  /**
   * Clear error logs
   */
  clearErrorLogs(): void {
    this.errorLogs = [];
    try {
      localStorage.removeItem('pomodoro_error_logs');
    } catch {
      // Ignore
    }
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<ErrorHandlerConfig>): void {
    this.config = { ...this.config, ...config };
  }
}

// ============================================================================
// SINGLETON INSTANCE
// ============================================================================

/**
 * Global error handler instance
 */
let errorHandlerInstance: ErrorHandlerService | null = null;

/**
 * Get or create error handler instance
 */
export function getErrorHandler(
  config?: Partial<ErrorHandlerConfig>
): ErrorHandlerService {
  if (!errorHandlerInstance) {
    errorHandlerInstance = new ErrorHandlerService(config);
  }
  return errorHandlerInstance;
}

/**
 * Reset error handler (useful for testing)
 */
export function resetErrorHandler(): void {
  errorHandlerInstance = null;
}

// ============================================================================
// CONVENIENCE FUNCTIONS
// ============================================================================

/**
 * Handle error with default handler
 */
export function handleError(
  error: Error | AppError | unknown,
  context?: ErrorContext
): ErrorLog {
  return getErrorHandler().handleError(error, context);
}

/**
 * Handle async error
 */
export function handleAsyncError(
  error: unknown,
  context?: ErrorContext
): ErrorLog {
  return getErrorHandler().handleAsyncError(error, context);
}

/**
 * Wrap async function with error handling
 */
export function withErrorHandling<T extends (...args: any[]) => any>(
  fn: T,
  context?: ErrorContext
): T {
  return ((...args: any[]) => {
    try {
      const result = fn(...args);

      // Handle promises
      if (result instanceof Promise) {
        return result.catch((error) => {
          handleAsyncError(error, context);
          throw error; // Re-throw for caller to handle
        });
      }

      return result;
    } catch (error) {
      handleError(error, context);
      throw error;
    }
  }) as T;
}

/**
 * Create error handler for specific component
 */
export function createComponentErrorHandler(componentName: string) {
  return {
    handle: (error: Error | unknown, action?: string) => {
      return handleError(error, {
        component: componentName,
        action,
      });
    },
  };
}

