/**
 * Create a new task with default values
 */
export function createTask(data: Partial<Task> = {}): Task {
  const now = Date.now();
  return {
    id: data.id || generateId(),
    title: data.title || 'New Task',
    description: data.description,
    priority: data.priority || ('medium' as TaskPriority),
    status: data.status || ('todo' as TaskStatus),
    estimatedPomodoros: data.estimatedPomodoros || 1,
    completedPomodoros: data.completedPomodoros || 0,
    tags: data.tags || [],
    createdAt: data.createdAt || now,
    updatedAt: now,
    dueDate: data.dueDate,
    projectId: data.projectId,
  };
}

/**
 * Create a new session with default values
 */
export function createSession(data: Partial<Session> = {}): Session {
  const now = Date.now();
  return {
    id: data.id || generateId(),
    taskId: data.taskId ?? null,
    type: data.type || ('work' as SessionType),
    duration: data.duration || 25 * 60,
    actualDuration: data.actualDuration || 0,
    startedAt: data.startedAt || now,
    completedAt: data.completedAt,
    wasCompleted: data.wasCompleted || false,
    wasSkipped: data.wasSkipped || false,
    notes: data.notes,
    createdAt: data.createdAt || now,
  };
}

// Re-export types for convenience
export type {
  Task,
  Session,
  TimerSettings,
  AppSettings,
  DailyStats,
  Statistics,
  BackupData,
  StorageEvent,
  StorageEventListener,
};

export { StorageType, LS_KEYS };

/**
 * Pomodoro Timer - Core State Machine
 * High-precision timer with pause/resume support and automatic state transitions
 */

import {
  TimerState,
  TimerEvent,
  TimerEventType,
  TimerObserver,
  SessionType,
  Task,
  TimerSettings,
} from '../types';

/**
 * Timer configuration options
 */
interface TimerOptions {
  workDuration: number;
  shortBreakDuration: number;
  longBreakDuration: number;
  longBreakInterval: number;
  onTick?: (remaining: number, total: number) => void;
  onStateChange?: (event: TimerEvent) => void;
  onComplete?: () => void;
}

/**
 * Timer session data
 */
interface TimerSession {
  type: SessionType;
  totalDuration: number;
  remainingTime: number;
  startTime: number | null;
  pausedAt: number | null;
  accumulatedPause: number;
}

/**
 * PomodoroTimer class implementing a high-precision timer state machine
 * Uses Date.now() delta for accurate timing regardless of main thread blocking
 */
export class PomodoroTimer {
  private state: TimerState;
  private session: TimerSession | null;
  private settings: TimerSettings;
  private currentTask: Task | null;
  private intervalId: number | null;
  private observers: Set<TimerObserver>;
  private completedWorkSessions: number;
  private lastTickTime: number;
  private tickInterval: number;

  // Default settings
  private static readonly DEFAULT_SETTINGS: TimerSettings = {
    workDuration: 1500, // 25 minutes
    shortBreakDuration: 300, // 5 minutes
    longBreakDuration: 900, // 15 minutes
    longBreakInterval: 4, // Every 4 work sessions
    autoStartBreak: false,
    autoStartWork: false,
    notificationEnabled: true,
    soundEnabled: true,
    volume: 0.7,
  };

  constructor(settings?: Partial<TimerSettings>) {
    this.state = TimerState.IDLE;
    this.session = null;
    this.settings = { ...PomodoroTimer.DEFAULT_SETTINGS, ...settings };
    this.currentTask = null;
    this.intervalId = null;
    this.observers = new Set();
    this.completedWorkSessions = 0;
    this.lastTickTime = 0;
    this.tickInterval = 100; // Update every 100ms
  }

  /**
   * Start a timer session
   * @param type - Session type (work, short_break, long_break)
   * @param task - Optional task to associate with this session
   * @param duration - Optional custom duration in seconds
   */
  public async start(
    type: 'work' | 'short_break' | 'long_break',
    task?: Task | null,
    duration?: number
  ): Promise<void> {
    // Validate state transitions
    if (
      this.state === TimerState.WORKING ||
      this.state === TimerState.SHORT_BREAK ||
      this.state === TimerState.LONG_BREAK
    ) {
      throw new Error('Cannot start timer: already running');
    }

    // Set current task
    this.currentTask = task || null;

    // Determine session type and duration
    const sessionType = this.mapToSessionType(type);
    const totalDuration = duration ?? this.getDurationForType(type);

    // Initialize session
    this.session = {
      type: sessionType,
      totalDuration,
      remainingTime: totalDuration,
      startTime: Date.now(),
      pausedAt: null,
      accumulatedPause: 0,
    };

    // Update state
    this.setState(this.mapToTimerState(type));

    // Emit started event
    this.emitEvent({
      type: TimerEventType.STARTED,
      state: this.state,
      remainingTime: this.session.remainingTime,
      timestamp: Date.now(),
      taskId: this.currentTask?.id,
      sessionType: this.session.type,
    });

    // Start the timer loop
    this.startTimerLoop();
  }

  /**
   * Pause the current timer session
   */
  public pause(): void {
    if (
      this.state !== TimerState.WORKING &&
      this.state !== TimerState.SHORT_BREAK &&
      this.state !== TimerState.LONG_BREAK
    ) {
      throw new Error('Cannot pause: timer is not running');
    }

    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }

    // Record pause time
    if (this.session) {
      this.session.pausedAt = Date.now();
    }

    // Update state
    this.setState(TimerState.PAUSED);

    // Emit paused event
    this.emitEvent({
      type: TimerEventType.PAUSED,
      state: this.state,
      remainingTime: this.session?.remainingTime ?? 0,
      timestamp: Date.now(),
      taskId: this.currentTask?.id,
      sessionType: this.session?.type,
    });
  }

  /**
   * Resume a paused timer session
   */
  public resume(): void {
    if (this.state !== TimerState.PAUSED) {
      throw new Error('Cannot resume: timer is not paused');
    }

    if (!this.session) {
      throw new Error('No session to resume');
    }

    // Calculate pause duration and add to accumulated pause time
    if (this.session.pausedAt !== null) {
      const pauseDuration = Date.now() - this.session.pausedAt;
      this.session.accumulatedPause += pauseDuration;
      this.session.pausedAt = null;
    }

    // Update state based on session type
    this.setState(this.mapToTimerState(this.session.type));

    // Emit resumed event
    this.emitEvent({
      type: TimerEventType.RESUMED,
      state: this.state,
      remainingTime: this.session.remainingTime,
      timestamp: Date.now(),
      taskId: this.currentTask?.id,
      sessionType: this.session.type,
    });

    // Restart the timer loop
    this.startTimerLoop();
  }

  /**
   * Reset the timer to idle state
   */
  public reset(): void {
    this.stopTimerLoop();

    const previousState = this.state;
    this.session = null;
    this.setState(TimerState.IDLE);

    // Emit reset event
    this.emitEvent({
      type: TimerEventType.RESET,
      state: this.state,
      remainingTime: 0,
      timestamp: Date.now(),
      sessionType: undefined,
    });
  }

  /**
   * Skip the current session
   */
  public skip(): void {
    const sessionType = this.session?.type;
    const wasCompleted = false;

    this.stopTimerLoop();
    this.session = null;
    this.setState(TimerState.IDLE);

    // Emit skipped event
    this.emitEvent({
      type: TimerEventType.SKIPPED,
      state: this.state,
      remainingTime: 0,
      timestamp: Date.now(),
      taskId: this.currentTask?.id,
      sessionType,
    });
  }

  /**
   * Get the current timer state
   */
  public getState(): TimerState {
    return this.state;
  }

  /**
   * Get remaining time in seconds
   */
  public getRemainingTime(): number {
    if (!this.session) {
      return 0;
    }

    if (this.state === TimerState.PAUSED || this.state === TimerState.IDLE) {
      return this.session.remainingTime;
    }

    // Calculate real-time remaining
    const now = Date.now();
    const elapsed =
      now - (this.session.startTime ?? now) - this.session.accumulatedPause;
    const remaining = Math.max(
      0,
      this.session.totalDuration - Math.floor(elapsed / 1000)
    );

    return remaining;
  }

  /**
   * Get total duration of current session in seconds
   */
  public getTotalDuration(): number {
    return this.session?.totalDuration ?? 0;
  }

  /**
   * Get progress as a value between 0 and 1
   */
  public getProgress(): number {
    if (!this.session || this.session.totalDuration <= 0) {
      return 0;
    }

    const remaining = this.getRemainingTime();
    return Math.max(0, Math.min(1, 1 - remaining / this.session.totalDuration));
  }

  /**
   * Get the current task associated with the timer
   */
  public getCurrentTask(): Task | null {
    return this.currentTask;
  }

  /**
   * Get the current session type
   */
  public getSessionType(): SessionType | null {
    return this.session?.type ?? null;
  }

  /**
   * Get the number of completed work sessions
   */
  public getCompletedWorkSessions(): number {
    return this.completedWorkSessions;
  }

  /**
   * Check if timer is currently running
   */
  public isRunning(): boolean {
    return (
      this.state === TimerState.WORKING ||
      this.state === TimerState.SHORT_BREAK ||
      this.state === TimerState.LONG_BREAK
    );
  }

  /**
   * Check if timer is paused
   */
  public isPaused(): boolean {
    return this.state === TimerState.PAUSED;
  }

  /**
   * Check if timer is idle
   */
  public isIdle(): boolean {
    return this.state === TimerState.IDLE;
  }

  /**
   * Update timer settings
   */
  public updateSettings(settings: Partial<TimerSettings>): void {
    this.settings = { ...this.settings, ...settings };
  }

  /**
   * Get current timer settings
   */
  public getSettings(): TimerSettings {
    return { ...this.settings };
  }

  /**
   * Subscribe to timer events
   */
  public subscribe(observer: TimerObserver): () => void {
    this.observers.add(observer);
    return () => this.observers.delete(observer);
  }

  /**
   * Get the next break type based on completed work sessions
   */
  public getNextBreakType(): 'short_break' | 'long_break' {
    return (this.completedWorkSessions + 1) %
      this.settings.longBreakInterval ===
      0
      ? 'long_break'
      : 'short_break';
  }

  /**
   * Get duration for a specific session type
   */
  private getDurationForType(
    type: 'work' | 'short_break' | 'long_break'
  ): number {
    switch (type) {
      case 'work':
        return this.settings.workDuration;
      case 'short_break':
        return this.settings.shortBreakDuration;
      case 'long_break':
        return this.settings.longBreakDuration;
    }
  }

  /**
   * Map session type string to SessionType enum
   */
  private mapToSessionType(
    type: 'work' | 'short_break' | 'long_break'
  ): SessionType {
    switch (type) {
      case 'work':
        return SessionType.WORK;
      case 'short_break':
        return SessionType.SHORT_BREAK;
      case 'long_break':
        return SessionType.LONG_BREAK;
    }
  }

  /**
   * Map session type string to TimerState
   */
  private mapToTimerState(
    type: 'work' | 'short_break' | 'long_break' | SessionType
  ): TimerState {
    if (type === SessionType.WORK || type === 'work') {
      return TimerState.WORKING;
    }
    if (type === SessionType.SHORT_BREAK || type === 'short_break') {
      return TimerState.SHORT_BREAK;
    }
    return TimerState.LONG_BREAK;
  }

  /**
   * Update timer state and notify observers
   */
  private setState(newState: TimerState): void {
    if (this.state !== newState) {
      const oldState = this.state;
      this.state = newState;

      this.emitEvent({
        type: TimerEventType.STATE_CHANGED,
        state: this.state,
        remainingTime: this.getRemainingTime(),
        timestamp: Date.now(),
        taskId: this.currentTask?.id,
        sessionType: this.session?.type,
      });
    }
  }

  /**
   * Start the main timer loop
   */
  private startTimerLoop(): void {
    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
    }

    this.lastTickTime = Date.now();

    this.intervalId = window.setInterval(() => {
      this.tick();
    }, this.tickInterval);
  }

  /**
   * Stop the timer loop
   */
  private stopTimerLoop(): void {
    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  /**
   * Main timer tick function - called every 100ms
   * Uses Date.now() delta for high-precision timing
   */
  private tick(): void {
    if (!this.session || this.state === TimerState.PAUSED) {
      return;
    }

    const now = Date.now();
    const elapsed =
      now - (this.session.startTime ?? now) - this.session.accumulatedPause;
    const elapsedSeconds = Math.floor(elapsed / 1000);

    // Calculate remaining time
    this.session.remainingTime = Math.max(
      0,
      this.session.totalDuration - elapsedSeconds
    );

    // Check if timer completed
    if (this.session.remainingTime <= 0) {
      this.completeSession();
      return;
    }

    // Notify observers of tick
    this.observers.forEach((observer) => {
      try {
        observer({
          type: TimerEventType.STATE_CHANGED,
          state: this.state,
          remainingTime: this.session!.remainingTime,
          timestamp: now,
          taskId: this.currentTask?.id,
          sessionType: this.session!.type,
        });
      } catch (error) {
        console.error('Error in timer observer:', error);
      }
    });
  }

  /**
   * Handle session completion
   */
  private completeSession(): void {
    const sessionType = this.session?.type;
    const wasCompleted = true;

    // If this was a work session, increment counter
    if (sessionType === SessionType.WORK) {
      this.completedWorkSessions++;

      // Update task's completed pomodoros
      if (this.currentTask) {
        this.currentTask.completedPomodoros++;
      }
    }

    this.stopTimerLoop();
    this.setState(TimerState.IDLE);

    // Emit completed event
    this.emitEvent({
      type: TimerEventType.COMPLETED,
      state: this.state,
      remainingTime: 0,
      timestamp: Date.now(),
      taskId: this.currentTask?.id,
      sessionType,
    });

    // Clear session but keep data for controller to read
    const completedSession = this.session;
    this.session = null;

    // Notify observers
    this.observers.forEach((observer) => {
      try {
        observer({
          type: TimerEventType.COMPLETED,
          state: this.state,
          remainingTime: 0,
          timestamp: Date.now(),
          taskId: this.currentTask?.id,
          sessionType: completedSession?.type,
        });
      } catch (error) {
        console.error('Error in timer observer:', error);
      }
    });
  }

  /**
   * Emit a timer event to all observers
   */
  private emitEvent(event: TimerEvent): void {
    this.observers.forEach((observer) => {
      try {
        observer(event);
      } catch (error) {
        console.error('Error in timer observer:', error);
      }
    });
  }

  /**
   * Get session data for recording purposes
   */
  public getSessionData(): {
    type: SessionType;
    duration: number;
    startedAt: number;
    completedAt: number | null;
    taskId: string | null;
  } | null {
    if (!this.session) {
      return null;
    }

    return {
      type: this.session.type,
      duration: this.session.totalDuration,
      startedAt: this.session.startTime ?? Date.now(),
      completedAt: this.state === TimerState.IDLE ? Date.now() : null,
      taskId: this.currentTask?.id ?? null,
    };
  }

  /**
   * Set the current task
   */
  public setCurrentTask(task: Task | null): void {
    this.currentTask = task;
  }

  /**
   * Cleanup and release resources
   */
  public dispose(): void {
    this.stopTimerLoop();
    this.observers.clear();
    this.session = null;
    this.currentTask = null;
    this.setState(TimerState.IDLE);
  }
}

/**
 * Factory function to create a new PomodoroTimer instance
 */
export function createPomodoroTimer(
  settings?: Partial<TimerSettings>
): PomodoroTimer {
  return new PomodoroTimer(settings);
}

/**
 * Timer Controller
 * High-level controller that orchestrates timer, storage, notifications, and audio
 */

import { PomodoroTimer } from './timer';
import {
  IStorageService,
  Session,
  SessionType,
  Task,
  TimerEvent,
  TimerEventType,
  TimerSettings,
} from '../types';
import { getAudioManager, AudioManager } from './audioManager';
import { NotificationManager } from './notificationManager';
import { v4 as uuidv4 } from 'uuid';

/**
 * Controller configuration options
 */
interface TimerControllerOptions {
  storage: IStorageService;
  audioManager?: AudioManager;
  notificationManager?: NotificationManager;
  settings?: Partial<TimerSettings>;
}

/**
 * Session recording data
 */
interface SessionRecordingData {
  taskId: string | null;
  type: SessionType;
  duration: number;
  actualDuration: number;
  startedAt: number;
  completedAt: number;
  wasCompleted: boolean;
  wasSkipped: boolean;
  notes?: string;
}

/**
 * TimerController class
 * Orchestrates all timer-related operations including session recording,
 * notifications, and automatic state transitions
 */
export class TimerController {
  private timer: PomodoroTimer;
  private storage: IStorageService;
  private audioManager: AudioManager;
  private notificationManager: NotificationManager;
  private currentSessionStartTime: number | null;
  private isDisposed: boolean;
  private unsubscribeFromEvents: (() => void) | null;
  private warningTimeouts: Set<number>;

  // Warning times in seconds before session ends
  private static readonly WARNING_TIMES = [60, 300]; // 1 min, 5 mins

  constructor(options: TimerControllerOptions) {
    this.storage = options.storage;
    this.audioManager = options.audioManager ?? getAudioManager();
    this.notificationManager =
      options.notificationManager ?? new NotificationManager();
    this.currentSessionStartTime = null;
    this.isDisposed = false;
    this.unsubscribeFromEvents = null;
    this.warningTimeouts = new Set();

    // Initialize timer with settings
    this.timer = new PomodoroTimer(options.settings);

    // Subscribe to timer events
    this.setupEventListeners();

    // Initialize settings from storage
    this.initializeSettings();
  }

  /**
   * Initialize settings from storage
   */
  private async initializeSettings(): Promise<void> {
    try {
      const settings = await this.storage.getSettings();
      this.timer.updateSettings(settings);
      this.audioManager.setVolume(settings.volume);
    } catch (error) {
      console.error('Error initializing settings:', error);
    }
  }

  /**
   * Setup event listeners for timer events
   */
  private setupEventListeners(): void {
    this.unsubscribeFromEvents = this.timer.subscribe((event: TimerEvent) => {
      this.handleTimerEvent(event);
    });
  }

  /**
   * Handle timer events
   */
  private handleTimerEvent(event: TimerEvent): void {
    if (this.isDisposed) {
      return;
    }

    switch (event.type) {
      case TimerEventType.STARTED:
        this.handleTimerStarted(event);
        break;
      case TimerEventType.PAUSED:
        this.handleTimerPaused(event);
        break;
      case TimerEventType.RESUMED:
        this.handleTimerResumed(event);
        break;
      case TimerEventType.COMPLETED:
        this.handleTimerCompleted(event);
        break;
      case TimerEventType.SKIPPED:
        this.handleTimerSkipped(event);
        break;
      case TimerEventType.RESET:
        this.handleTimerReset(event);
        break;
    }
  }

  /**
   * Handle timer started event
   */
  private handleTimerStarted(event: TimerEvent): void {
    this.currentSessionStartTime = event.timestamp;

    // Play start sound
    if (this.timer.getSettings().soundEnabled) {
      switch (event.sessionType) {
        case SessionType.WORK:
          this.audioManager.playStartSound();
          break;
        case SessionType.SHORT_BREAK:
        case SessionType.LONG_BREAK:
          this.audioManager.playBreakStartSound();
          break;
      }
    }

    // Send notification if document is hidden
    this.sendNotificationIfNeeded(
      this.getSessionStartTitle(event.sessionType),
      this.getSessionStartMessage(event.sessionType)
    );

    // Schedule warning notifications
    this.scheduleWarningNotifications(event.remainingTime);
  }

  /**
   * Handle timer paused event
   */
  private handleTimerPaused(event: TimerEvent): void {
    // Play pause sound
    if (this.timer.getSettings().soundEnabled) {
      this.audioManager.playPauseSound();
    }

    // Clear warning timeouts
    this.clearWarningTimeouts();
  }

  /**
   * Handle timer resumed event
   */
  private handleTimerResumed(event: TimerEvent): void {
    // Reschedule warning notifications
    this.scheduleWarningNotifications(event.remainingTime);
  }

  /**
   * Handle timer completed event
   */
  private async handleTimerCompleted(event: TimerEvent): Promise<void> {
    // Clear warning timeouts
    this.clearWarningTimeouts();

    // Play completion sound
    if (this.timer.getSettings().soundEnabled) {
      this.audioManager.playCompleteSound();
    }

    // Record the session
    const session = await this.recordSession(true, false);
    if (!session) {
      console.error('Failed to record session');
      return;
    }

    // Send completion notification
    await this.sendCompletionNotification(event.sessionType, session);

    // Handle auto-start behavior
    await this.handleAutoStart(event.sessionType);
  }

  /**
   * Handle timer skipped event
   */
  private async handleTimerSkipped(event: TimerEvent): Promise<void> {
    // Clear warning timeouts
    this.clearWarningTimeouts();

    // Record the skipped session
    await this.recordSession(false, true);
  }

  /**
   * Handle timer reset event
   */
  private handleTimerReset(event: TimerEvent): void {
    // Clear warning timeouts
    this.clearWarningTimeouts();
    this.currentSessionStartTime = null;
  }

  /**
   * Schedule warning notifications for remaining time
   */
  private scheduleWarningNotifications(remainingTime: number): void {
    this.clearWarningTimeouts();

    if (!this.timer.getSettings().notificationEnabled) {
      return;
    }

    TimerController.WARNING_TIMES.forEach((warningTime) => {
      if (remainingTime > warningTime) {
        const delay = (remainingTime - warningTime) * 1000;
        const timeoutId = window.setTimeout(() => {
          const minutes = Math.floor(warningTime / 60);
          if (minutes > 0) {
            this.notificationManager.notifyTimeRemaining(minutes);
          }
        }, delay);
        this.warningTimeouts.add(timeoutId);
      }
    });
  }

  /**
   * Clear all warning notification timeouts
   */
  private clearWarningTimeouts(): void {
    this.warningTimeouts.forEach((timeoutId) => {
      clearTimeout(timeoutId);
    });
    this.warningTimeouts.clear();
  }

  /**
   * Send notification only if document is hidden
   */
  private async sendNotificationIfNeeded(
    title: string,
    message: string
  ): Promise<void> {
    if (!this.timer.getSettings().notificationEnabled) {
      return;
    }

    if (document.hidden) {
      await this.notificationManager.send(title, message);
    }
  }

  /**
   * Get session start notification title
   */
  private getSessionStartTitle(sessionType?: SessionType): string {
    switch (sessionType) {
      case SessionType.WORK:
        return 'Work session started';
      case SessionType.SHORT_BREAK:
        return 'Short break started';
      case SessionType.LONG_BREAK:
        return 'Long break started';
      default:
        return 'Timer started';
    }
  }

  /**
   * Get session start notification message
   */
  private getSessionStartMessage(sessionType?: SessionType): string {
    const currentTask = this.timer.getCurrentTask();

    switch (sessionType) {
      case SessionType.WORK:
        return currentTask
          ? `Working on: ${currentTask.title}`
          : 'Focus on your work!';
      case SessionType.SHORT_BREAK:
        return 'Take a short break.';
      case SessionType.LONG_BREAK:
        return 'Take a longer break.';
      default:
        return '';
    }
  }

  /**
   * Send completion notification based on session type
   */
  private async sendCompletionNotification(
    sessionType: SessionType | undefined,
    session: Session
  ): Promise<void> {
    if (!this.timer.getSettings().notificationEnabled) {
      return;
    }

    const currentTask = this.timer.getCurrentTask();

    switch (sessionType) {
      case SessionType.WORK:
        await this.notificationManager.notifyWorkComplete(
          currentTask?.title ?? '',
          this.timer.getCompletedWorkSessions()
        );
        break;
      case SessionType.SHORT_BREAK:
      case SessionType.LONG_BREAK:
        await this.notificationManager.notifyBreakOver();
        break;
    }
  }

  /**
   * Handle auto-start behavior after session completion
   */
  private async handleAutoStart(
    completedSessionType: SessionType | undefined
  ): Promise<void> {
    const settings = this.timer.getSettings();

    if (completedSessionType === SessionType.WORK && settings.autoStartBreak) {
      // Auto-start break
      await this.autoStartBreak();
    } else if (
      (completedSessionType === SessionType.SHORT_BREAK ||
        completedSessionType === SessionType.LONG_BREAK) &&
      settings.autoStartWork
    ) {
      // Auto-start next work session
      const currentTask = this.timer.getCurrentTask();
      if (currentTask) {
        await this.startWorkSession(currentTask);
      }
    }
  }

  /**
   * Start a work session
   * @param task - Task to associate with this work session
   * @param customDuration - Optional custom duration in seconds
   */
  public async startWorkSession(
    task: Task,
    customDuration?: number
  ): Promise<void> {
    this.timer.setCurrentTask(task);
    await this.timer.start('work', task, customDuration);
  }

  /**
   * Start a short break session
   * @param customDuration - Optional custom duration in seconds
   */
  public async startShortBreak(customDuration?: number): Promise<void> {
    await this.timer.start('short_break', null, customDuration);
  }

  /**
   * Start a long break session
   * @param customDuration - Optional custom duration in seconds
   */
  public async startLongBreak(customDuration?: number): Promise<void> {
    await this.timer.start('long_break', null, customDuration);
  }

  /**
   * Auto-start appropriate break based on completed work sessions
   */
  public async autoStartBreak(): Promise<void> {
    const isLongBreak = this.timer.getNextBreakType() === 'long_break';

    if (isLongBreak) {
      await this.startLongBreak();
    } else {
      await this.startShortBreak();
    }
  }

  /**
   * Pause the current timer
   */
  public pause(): void {
    this.timer.pause();
  }

  /**
   * Resume the paused timer
   */
  public resume(): void {
    this.timer.resume();
  }

  /**
   * Reset the timer to idle state
   */
  public reset(): void {
    this.timer.reset();
  }

  /**
   * Skip the current session
   */
  public skip(): void {
    this.timer.skip();
  }

  /**
   * Complete current pomodoro and record session
   */
  public async completePomodoro(): Promise<void> {
    if (
      this.timer.getState() !== 'working' &&
      this.timer.getState() !== 'paused'
    ) {
      throw new Error('No active work session to complete');
    }

    // Record session before resetting
    await this.recordSession(true, false);

    // Reset timer
    this.reset();
  }

  /**
   * Record the current session to storage
   */
  private async recordSession(
    wasCompleted: boolean,
    wasSkipped: boolean
  ): Promise<Session | null> {
    const sessionData = this.timer.getSessionData();

    if (!sessionData) {
      return null;
    }

    const currentTask = this.timer.getCurrentTask();
    const completedAt = Date.now();
    const actualDuration = wasCompleted
      ? sessionData.duration
      : Math.floor((completedAt - sessionData.startedAt) / 1000);

    const session: Session = {
      id: uuidv4(),
      taskId: sessionData.taskId,
      type: sessionData.type,
      duration: sessionData.duration,
      actualDuration,
      startedAt: sessionData.startedAt,
      completedAt,
      wasCompleted,
      wasSkipped,
    };

    try {
      await this.storage.saveSession(session);

      // Update task's completed pomodoros if work session was completed
      if (
        sessionData.type === SessionType.WORK &&
        wasCompleted &&
        currentTask
      ) {
        currentTask.completedPomodoros++;
        await this.storage.saveTask(currentTask);
      }

      return session;
    } catch (error) {
      console.error('Error recording session:', error);
      return null;
    }
  }

  /**
   * Get recent sessions
   */
  public async getRecentSessions(limit: number = 10): Promise<Session[]> {
    try {
      return await this.storage.getLatestSessions(limit);
    } catch (error) {
      console.error('Error getting recent sessions:', error);
      return [];
    }
  }

  /**
   * Get sessions for a specific task
   */
  public async getSessionsForTask(taskId: string): Promise<Session[]> {
    try {
      return await this.storage.getSessionsByTask(taskId);
    } catch (error) {
      console.error('Error getting sessions for task:', error);
      return [];
    }
  }

  /**
   * Update timer settings
   */
  public async updateSettings(settings: Partial<TimerSettings>): Promise<void> {
    // Update timer settings
    this.timer.updateSettings(settings);

    // Update audio manager
    if (settings.volume !== undefined) {
      this.audioManager.setVolume(settings.volume);
    }

    // Save to storage
    try {
      await this.storage.saveSettings(settings);
    } catch (error) {
      console.error('Error saving settings:', error);
    }
  }

  /**
   * Request notification permission
   */
  public async requestNotificationPermission(): Promise<boolean> {
    return await this.notificationManager.requestPermission();
  }

  /**
   * Check if notifications are enabled
   */
  public areNotificationsEnabled(): boolean {
    return this.notificationManager.isEnabled();
  }

  /**
   * Toggle sound on/off
   */
  public toggleSound(): void {
    const settings = this.timer.getSettings();
    const newState = !settings.soundEnabled;

    this.timer.updateSettings({ soundEnabled: newState });

    if (!newState) {
      this.audioManager.mute();
    } else {
      this.audioManager.unmute();
    }
  }

  /**
   * Toggle notifications on/off
   */
  public toggleNotifications(): void {
    const settings = this.timer.getSettings();
    const newState = !settings.notificationEnabled;

    this.timer.updateSettings({ notificationEnabled: newState });
  }

  /**
   * Set volume level
   */
  public setVolume(volume: number): void {
    const clampedVolume = Math.max(0, Math.min(1, volume));
    this.audioManager.setVolume(clampedVolume);
    this.timer.updateSettings({ volume: clampedVolume });
  }

  /**
   * Get the underlying timer instance
   */
  public getTimer(): PomodoroTimer {
    return this.timer;
  }

  /**
   * Get audio manager instance
   */
  public getAudioManager(): AudioManager {
    return this.audioManager;
  }

  /**
   * Get notification manager instance
   */
  public getNotificationManager(): NotificationManager {
    return this.notificationManager;
  }

  /**
   * Get current timer state
   */
  public getState(): string {
    return this.timer.getState();
  }

  /**
   * Get remaining time in seconds
   */
  public getRemainingTime(): number {
    return this.timer.getRemainingTime();
  }

  /**
   * Get progress as a value between 0 and 1
   */
  public getProgress(): number {
    return this.timer.getProgress();
  }

  /**
   * Get current task
   */
  public getCurrentTask(): Task | null {
    return this.timer.getCurrentTask();
  }

  /**
   * Subscribe to timer events
   */
  public subscribe(callback: (event: TimerEvent) => void): () => void {
    return this.timer.subscribe(callback);
  }

  /**
   * Dispose of controller and release resources
   */
  public dispose(): void {
    this.isDisposed = true;

    // Clear warning timeouts
    this.clearWarningTimeouts();

    // Unsubscribe from timer events
    if (this.unsubscribeFromEvents) {
      this.unsubscribeFromEvents();
      this.unsubscribeFromEvents = null;
    }

    // Dispose timer
    this.timer.dispose();

    // Clear references
    this.currentSessionStartTime = null;
  }
}

/**
 * Factory function to create a TimerController instance
 */
export async function createTimerController(
  storage: IStorageService,
  options?: Partial<TimerControllerOptions>
): Promise<TimerController> {
  const controller = new TimerController({
    storage,
    ...options,
  });

  return controller;
}

/**
 * AppStore - Centralized State Management
 *
 * Implements a unidirectional data flow pattern with:
 * - Single source of truth (AppState)
 * - Read-only state exposure
 * - Explicit state mutation methods
 * - Subscriber notifications on state changes
 * - Immutable state updates
 */

import {
  AppState,
  StateListener,
  UnsubscribeFn,
  Task,
  TaskStatus,
  TaskPriority,
  TimerState,
  SessionType,
  TimerSettings,
  Session,
  DailyStats,
  Project,
  TaskFilter,
  Statistics,
  TimerEventType,
  TimerEvent,
} from '../types/index';

/**
 * Default timer settings
 */
const DEFAULT_TIMER_SETTINGS: TimerSettings = {
  workDuration: 25 * 60, // 25 minutes
  shortBreakDuration: 5 * 60, // 5 minutes
  longBreakDuration: 15 * 60, // 15 minutes
  longBreakInterval: 4, // 4 pomodoros before long break
  autoStartBreak: false,
  autoStartWork: false,
  notificationEnabled: true,
  soundEnabled: true,
  volume: 0.7,
};

/**
 * Initial application state
 */
const createInitialState = (): AppState => ({
  tasks: [],
  activeTaskId: null,
  timerState: TimerState.IDLE,
  remainingTime: DEFAULT_TIMER_SETTINGS.workDuration,
  currentSessionType: null,
  completedSessionsSinceLastLongBreak: 0,
  settings: DEFAULT_TIMER_SETTINGS,
  sessions: [],
  dailyStats: new Map(),
  projects: [],
  isLoading: false,
  error: null,
});

/**
 * Timer event observer interface
 */
export type TimerObserver = (event: TimerEvent) => void;

/**
 * AppStore - Central state management class
 *
 * Features:
 * - Immutable state updates
 * - Subscription-based notifications
 * - Event-driven timer management
 * - Task CRUD operations
 * - Session tracking
 */
export class AppStore {
  // Private state - only modified through store methods
  private state: AppState;

  // State change listeners
  private listeners: Set<StateListener> = new Set();

  // Timer-specific observers
  private timerObservers: Set<TimerObserver> = new Set();

  // State history for undo/redo (optional feature)
  private history: AppState[] = [];
  private historyIndex: number = -1;
  private maxHistorySize: number = 50;

  // Batch update flag
  private batchUpdateDepth: number = 0;
  private pendingNotification: boolean = false;

  constructor(initialState?: Partial<AppState>) {
    this.state = {
      ...createInitialState(),
      ...initialState,
      dailyStats: initialState?.dailyStats || new Map(),
    };
  }

  // ==========================================================================
  // STATE ACCESS - Read-only getters
  // ==========================================================================

  /**
   * Get current state (readonly snapshot)
   */
  getState(): Readonly<AppState> {
    return Object.freeze({ ...this.state });
  }

  /**
   * Get all tasks
   */
  getTasks(): Task[] {
    return [...this.state.tasks];
  }

  /**
   * Get tasks filtered by criteria
   */
  getFilteredTasks(filter: TaskFilter): Task[] {
    let filtered = [...this.state.tasks];

    if (filter.status && filter.status !== 'all') {
      filtered = filtered.filter((t) => t.status === filter.status);
    }

    if (filter.priority && filter.priority !== 'all') {
      filtered = filtered.filter((t) => t.priority === filter.priority);
    }

    if (filter.projectId && filter.projectId !== 'all') {
      filtered = filtered.filter((t) => t.projectId === filter.projectId);
    }

    if (filter.searchQuery) {
      const query = filter.searchQuery.toLowerCase();
      filtered = filtered.filter(
        (t) =>
          t.title.toLowerCase().includes(query) ||
          t.description?.toLowerCase().includes(query)
      );
    }

    if (filter.tags && filter.tags.length > 0) {
      filtered = filtered.filter((t) =>
        t.tags?.some((tag) => filter.tags!.includes(tag))
      );
    }

    if (filter.hideCompleted) {
      filtered = filtered.filter((t) => t.status !== TaskStatus.COMPLETED);
    }

    return filtered;
  }

  /**
   * Get active task
   */
  getActiveTask(): Task | null {
    if (!this.state.activeTaskId) return null;
    return (
      this.state.tasks.find((t) => t.id === this.state.activeTaskId) || null
    );
  }

  /**
   * Get task by ID
   */
  getTaskById(id: string): Task | null {
    return this.state.tasks.find((t) => t.id === id) || null;
  }

  /**
   * Get timer state
   */
  getTimerState(): TimerState {
    return this.state.timerState;
  }

  /**
   * Get remaining time
   */
  getRemainingTime(): number {
    return this.state.remainingTime;
  }

  /**
   * Get current session type
   */
  getCurrentSessionType(): SessionType | null {
    return this.state.currentSessionType;
  }

  /**
   * Get timer settings
   */
  getSettings(): TimerSettings {
    return { ...this.state.settings };
  }

  /**
   * Get all sessions
   */
  getSessions(): Session[] {
    return [...this.state.sessions];
  }

  /**
   * Get sessions for a specific task
   */
  getSessionsByTask(taskId: string): Session[] {
    return this.state.sessions.filter((s) => s.taskId === taskId);
  }

  /**
   * Get statistics summary
   */
  getStatistics(): Statistics {
    const today = new Date().toISOString().split('T')[0];
    const todayStats = this.state.dailyStats.get(today);

    const weekStart = this.getWeekStart();
    const weekStats = this.getWeekStats(weekStart);

    const overallStats = this.getOverallStats();

    return {
      today: {
        workSessions: todayStats?.workSessions || 0,
        totalWorkTime: todayStats?.totalWorkTime || 0,
        completedTasks: this.state.tasks.filter(
          (t) =>
            t.status === TaskStatus.COMPLETED &&
            new Date(t.updatedAt).toDateString() === new Date().toDateString()
        ).length,
        focusPercentage: this.calculateFocusPercentage(),
      },
      week: {
        workSessions: weekStats.workSessions,
        totalWorkTime: weekStats.totalWorkTime,
        completedTasks: weekStats.completedTasks,
        averageDailySessions: weekStats.averageDailySessions,
      },
      overall: {
        totalWorkSessions: overallStats.totalWorkSessions,
        totalWorkTime: overallStats.totalWorkTime,
        totalCompletedTasks: overallStats.totalCompletedTasks,
        longestStreak: overallStats.longestStreak,
      },
    };
  }

  /**
   * Get projects
   */
  getProjects(): Project[] {
    return [...this.state.projects];
  }

  /**
   * Check if loading
   */
  isLoading(): boolean {
    return this.state.isLoading;
  }

  /**
   * Get error message
   */
  getError(): string | null {
    return this.state.error;
  }

  // ==========================================================================
  // TASK OPERATIONS
  // ==========================================================================

  /**
   * Add a new task
   */
  async addTask(
    task: Omit<Task, 'id' | 'createdAt' | 'updatedAt'>
  ): Promise<string> {
    const now = Date.now();
    const newTask: Task = {
      ...task,
      id: this.generateId(),
      createdAt: now,
      updatedAt: now,
      completedPomodoros: task.completedPomodoros || 0,
    };

    this.updateState((draft) => {
      draft.tasks.push(newTask);
    });

    return newTask.id;
  }

  /**
   * Update an existing task
   */
  async updateTask(
    id: string,
    updates: Partial<Omit<Task, 'id' | 'createdAt'>>
  ): Promise<void> {
    this.updateState((draft) => {
      const index = draft.tasks.findIndex((t) => t.id === id);
      if (index === -1) {
        throw new Error(`Task with id ${id} not found`);
      }

      draft.tasks[index] = {
        ...draft.tasks[index],
        ...updates,
        updatedAt: Date.now(),
      };
    });
  }

  /**
   * Delete a task
   */
  async deleteTask(id: string): Promise<void> {
    this.updateState((draft) => {
      const index = draft.tasks.findIndex((t) => t.id === id);
      if (index === -1) {
        throw new Error(`Task with id ${id} not found`);
      }

      draft.tasks.splice(index, 1);

      // Clear active task if it was the deleted one
      if (draft.activeTaskId === id) {
        draft.activeTaskId = null;
      }
    });
  }

  /**
   * Set active task
   */
  async setActiveTask(id: string): Promise<void> {
    this.updateState((draft) => {
      const task = draft.tasks.find((t) => t.id === id);
      if (!task) {
        throw new Error(`Task with id ${id} not found`);
      }

      // Update previous active task status
      if (draft.activeTaskId) {
        const prevTask = draft.tasks.find((t) => t.id === draft.activeTaskId);
        if (prevTask && prevTask.status === TaskStatus.IN_PROGRESS) {
          prevTask.status = TaskStatus.TODO;
        }
      }

      // Set new active task
      draft.activeTaskId = id;
      task.status = TaskStatus.IN_PROGRESS;
      task.updatedAt = Date.now();
    });
  }

  /**
   * Clear active task
   */
  async clearActiveTask(): Promise<void> {
    this.updateState((draft) => {
      if (draft.activeTaskId) {
        const task = draft.tasks.find((t) => t.id === draft.activeTaskId);
        if (task && task.status === TaskStatus.IN_PROGRESS) {
          task.status = TaskStatus.TODO;
          task.updatedAt = Date.now();
        }
        draft.activeTaskId = null;
      }
    });
  }

  /**
   * Complete a task
   */
  async completeTask(id: string): Promise<void> {
    this.updateState((draft) => {
      const task = draft.tasks.find((t) => t.id === id);
      if (!task) {
        throw new Error(`Task with id ${id} not found`);
      }

      task.status = TaskStatus.COMPLETED;
      task.updatedAt = Date.now();

      // Update daily stats
      const today = new Date().toISOString().split('T')[0];
      const stats =
        draft.dailyStats.get(today) || this.createEmptyDailyStats(today);
      stats.completedTasks++;
      draft.dailyStats.set(today, stats);
    });
  }

  /**
   * Increment task pomodoro count
   */
  async incrementTaskPomodoros(id: string): Promise<void> {
    this.updateState((draft) => {
      const task = draft.tasks.find((t) => t.id === id);
      if (!task) {
        throw new Error(`Task with id ${id} not found`);
      }

      task.completedPomodoros++;
      task.updatedAt = Date.now();
    });
  }

  // ==========================================================================
  // TIMER OPERATIONS
  // ==========================================================================

  /**
   * Start timer
   */
  async startTimer(sessionType: SessionType = SessionType.WORK): Promise<void> {
    const duration = this.getDurationForSessionType(sessionType);

    this.updateState((draft) => {
      draft.timerState =
        sessionType === SessionType.WORK
          ? TimerState.WORKING
          : sessionType === SessionType.SHORT_BREAK
            ? TimerState.SHORT_BREAK
            : TimerState.LONG_BREAK;
      draft.currentSessionType = sessionType;
      draft.remainingTime = duration;
    });

    this.notifyTimerObservers({
      type: TimerEventType.STARTED,
      state: this.state.timerState,
      remainingTime: this.state.remainingTime,
      timestamp: Date.now(),
      taskId: this.state.activeTaskId,
      sessionType,
    });
  }

  /**
   * Pause timer
   */
  async pauseTimer(): Promise<void> {
    if (
      this.state.timerState === TimerState.IDLE ||
      this.state.timerState === TimerState.PAUSED
    ) {
      return;
    }

    this.updateState((draft) => {
      draft.timerState = TimerState.PAUSED;
    });

    this.notifyTimerObservers({
      type: TimerEventType.PAUSED,
      state: this.state.timerState,
      remainingTime: this.state.remainingTime,
      timestamp: Date.now(),
      taskId: this.state.activeTaskId,
      sessionType: this.state.currentSessionType!,
    });
  }

  /**
   * Resume timer
   */
  async resumeTimer(): Promise<void> {
    if (this.state.timerState !== TimerState.PAUSED) {
      return;
    }

    const previousState =
      this.state.currentSessionType === SessionType.WORK
        ? TimerState.WORKING
        : this.state.currentSessionType === SessionType.SHORT_BREAK
          ? TimerState.SHORT_BREAK
          : TimerState.LONG_BREAK;

    this.updateState((draft) => {
      draft.timerState = previousState;
    });

    this.notifyTimerObservers({
      type: TimerEventType.RESUMED,
      state: this.state.timerState,
      remainingTime: this.state.remainingTime,
      timestamp: Date.now(),
      taskId: this.state.activeTaskId,
      sessionType: this.state.currentSessionType!,
    });
  }

  /**
   * Reset timer
   */
  async resetTimer(): Promise<void> {
    const sessionType = this.state.currentSessionType || SessionType.WORK;
    const duration = this.getDurationForSessionType(sessionType);

    this.updateState((draft) => {
      draft.timerState = TimerState.IDLE;
      draft.remainingTime = duration;
      draft.currentSessionType = null;
    });

    this.notifyTimerObservers({
      type: TimerEventType.RESET,
      state: this.state.timerState,
      remainingTime: this.state.remainingTime,
      timestamp: Date.now(),
    });
  }

  /**
   * Update timer remaining time (called by timer interval)
   */
  async tickTimer(): Promise<void> {
    if (
      this.state.timerState === TimerState.IDLE ||
      this.state.timerState === TimerState.PAUSED
    ) {
      return;
    }

    const newRemainingTime = this.state.remainingTime - 1;

    this.updateState((draft) => {
      draft.remainingTime = newRemainingTime;
    });

    // Check if timer completed
    if (newRemainingTime <= 0) {
      await this.onTimerCompleted();
    }
  }

  /**
   * Handle timer completion
   */
  private async onTimerCompleted(): Promise<void> {
    const sessionType = this.state.currentSessionType!;
    const wasWorkSession = sessionType === SessionType.WORK;

    // Create session record
    const session: Session = {
      id: this.generateId(),
      taskId: this.state.activeTaskId,
      type: sessionType,
      duration: this.getDurationForSessionType(sessionType),
      actualDuration:
        this.getDurationForSessionType(sessionType) - this.state.remainingTime,
      startedAt:
        Date.now() - this.getDurationForSessionType(sessionType) * 1000,
      completedAt: Date.now(),
      wasCompleted: true,
      wasSkipped: false,
    };

    this.updateState((draft) => {
      // Save session
      draft.sessions.push(session);

      // Update daily stats
      const today = new Date().toISOString().split('T')[0];
      const stats =
        draft.dailyStats.get(today) || this.createEmptyDailyStats(today);

      if (wasWorkSession) {
        stats.workSessions++;
        stats.totalWorkTime += this.state.settings.workDuration;
        draft.completedSessionsSinceLastLongBreak++;

        // Update active task pomodoro count
        if (draft.activeTaskId) {
          const task = draft.tasks.find((t) => t.id === draft.activeTaskId);
          if (task) {
            task.completedPomodoros++;
          }
        }
      } else {
        stats.totalBreakTime +=
          sessionType === SessionType.SHORT_BREAK
            ? this.state.settings.shortBreakDuration
            : this.state.settings.longBreakDuration;
      }

      draft.dailyStats.set(today, stats);

      // Update streak
      stats.longestStreak = Math.max(
        stats.longestStreak,
        draft.completedSessionsSinceLastLongBreak
      );

      // Reset timer to idle
      draft.timerState = TimerState.IDLE;
      draft.currentSessionType = null;
      draft.remainingTime = draft.settings.workDuration;
    });

    this.notifyTimerObservers({
      type: TimerEventType.COMPLETED,
      state: this.state.timerState,
      remainingTime: 0,
      timestamp: Date.now(),
      taskId: this.state.activeTaskId,
      sessionType,
    });
  }

  /**
   * Skip current session
   */
  async skipSession(): Promise<void> {
    const sessionType = this.state.currentSessionType!;

    this.updateState((draft) => {
      // Create skipped session record
      const session: Session = {
        id: this.generateId(),
        taskId: draft.activeTaskId,
        type: sessionType,
        duration: this.getDurationForSessionType(sessionType),
        actualDuration:
          this.getDurationForSessionType(sessionType) - draft.remainingTime,
        startedAt:
          Date.now() -
          (this.getDurationForSessionType(sessionType) - draft.remainingTime) *
            1000,
        completedAt: Date.now(),
        wasCompleted: false,
        wasSkipped: true,
      };

      draft.sessions.push(session);

      // Reset timer
      draft.timerState = TimerState.IDLE;
      draft.currentSessionType = null;
      draft.remainingTime = draft.settings.workDuration;
    });

    this.notifyTimerObservers({
      type: TimerEventType.SKIPPED,
      state: this.state.timerState,
      remainingTime: this.state.remainingTime,
      timestamp: Date.now(),
      taskId: this.state.activeTaskId,
      sessionType,
    });
  }

  // ==========================================================================
  // SETTINGS OPERATIONS
  // ==========================================================================

  /**
   * Update timer settings
   */
  async updateSettings(settings: Partial<TimerSettings>): Promise<void> {
    this.updateState((draft) => {
      draft.settings = {
        ...draft.settings,
        ...settings,
      };
    });

    // Update remaining time if timer is idle
    if (this.state.timerState === TimerState.IDLE) {
      const duration = this.state.settings.workDuration;
      this.updateState((draft) => {
        draft.remainingTime = duration;
      });
    }
  }

  // ==========================================================================
  // PROJECT OPERATIONS
  // ==========================================================================

  /**
   * Add project
   */
  async addProject(
    project: Omit<Project, 'id' | 'createdAt'>
  ): Promise<string> {
    const newProject: Project = {
      ...project,
      id: this.generateId(),
      createdAt: Date.now(),
    };

    this.updateState((draft) => {
      draft.projects.push(newProject);
    });

    return newProject.id;
  }

  /**
   * Update project
   */
  async updateProject(
    id: string,
    updates: Partial<Omit<Project, 'id' | 'createdAt'>>
  ): Promise<void> {
    this.updateState((draft) => {
      const index = draft.projects.findIndex((p) => p.id === id);
      if (index === -1) {
        throw new Error(`Project with id ${id} not found`);
      }

      draft.projects[index] = {
        ...draft.projects[index],
        ...updates,
      };
    });
  }

  /**
   * Delete project
   */
  async deleteProject(id: string): Promise<void> {
    this.updateState((draft) => {
      const index = draft.projects.findIndex((p) => p.id === id);
      if (index === -1) {
        throw new Error(`Project with id ${id} not found`);
      }

      draft.projects.splice(index, 1);

      // Remove project reference from tasks
      draft.tasks.forEach((task) => {
        if (task.projectId === id) {
          task.projectId = undefined;
        }
      });
    });
  }

  // ==========================================================================
  // LOADING & ERROR STATES
  // ==========================================================================

  /**
   * Set loading state
   */
  setLoading(isLoading: boolean): void {
    this.updateState((draft) => {
      draft.isLoading = isLoading;
    });
  }

  /**
   * Set error message
   */
  setError(error: string | null): void {
    this.updateState((draft) => {
      draft.error = error;
    });
  }

  /**
   * Clear error
   */
  clearError(): void {
    this.setError(null);
  }

  // ==========================================================================
  // STATE RESTORATION
  // ==========================================================================

  /**
   * Restore state from storage
   */
  restoreState(savedState: AppState): void {
    this.state = {
      ...savedState,
      dailyStats: new Map(Object.entries(savedState.dailyStats as any)),
    };
    this.notifyListeners();
  }

  /**
   * Get serializable state for storage
   */
  getSerializableState(): any {
    return {
      ...this.state,
      dailyStats: Object.fromEntries(this.state.dailyStats),
    };
  }

  // ==========================================================================
  // SUBSCRIPTION MANAGEMENT
  // ==========================================================================

  /**
   * Subscribe to state changes
   * @returns Unsubscribe function
   */
  subscribe(listener: StateListener): UnsubscribeFn {
    this.listeners.add(listener);

    // Return unsubscribe function
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Subscribe to timer events
   * @returns Unsubscribe function
   */
  subscribeToTimer(observer: TimerObserver): UnsubscribeFn {
    this.timerObservers.add(observer);

    return () => {
      this.timerObservers.delete(observer);
    };
  }

  /**
   * Notify all state listeners
   */
  private notifyListeners(): void {
    const readonlyState = this.getState();
    this.listeners.forEach((listener) => {
      try {
        listener(readonlyState);
      } catch (error) {
        console.error('Error in state listener:', error);
      }
    });
  }

  /**
   * Notify timer observers
   */
  private notifyTimerObservers(event: TimerEvent): void {
    this.timerObservers.forEach((observer) => {
      try {
        observer(event);
      } catch (error) {
        console.error('Error in timer observer:', error);
      }
    });
  }

  // ==========================================================================
  // BATCH UPDATES
  // ==========================================================================

  /**
   * Start a batch update (prevents multiple notifications)
   */
  beginBatchUpdate(): void {
    this.batchUpdateDepth++;
  }

  /**
   * End a batch update and notify if needed
   */
  endBatchUpdate(): void {
    this.batchUpdateDepth--;
    if (this.batchUpdateDepth <= 0 && this.pendingNotification) {
      this.batchUpdateDepth = 0;
      this.pendingNotification = false;
      this.notifyListeners();
    }
  }

  /**
   * Execute a function within a batch update
   */
  async batch<T>(fn: () => T): Promise<T> {
    this.beginBatchUpdate();
    try {
      const result = await fn();
      return result;
    } finally {
      this.endBatchUpdate();
    }
  }

  // ==========================================================================
  // STATE HISTORY (Undo/Redo)
  // ==========================================================================

  /**
   * Undo last state change
   */
  undo(): void {
    if (this.historyIndex > 0) {
      this.historyIndex--;
      this.state = { ...this.history[this.historyIndex] };
      this.notifyListeners();
    }
  }

  /**
   * Redo last undone change
   */
  redo(): void {
    if (this.historyIndex < this.history.length - 1) {
      this.historyIndex++;
      this.state = { ...this.history[this.historyIndex] };
      this.notifyListeners();
    }
  }

  /**
   * Clear history
   */
  clearHistory(): void {
    this.history = [];
    this.historyIndex = -1;
  }

  // ==========================================================================
  // PRIVATE HELPER METHODS
  // ==========================================================================

  /**
   * Core state update method with immutable pattern
   */
  private updateState(updater: (draft: AppState) => void): void {
    // Save to history if not in batch mode
    if (this.batchUpdateDepth === 0) {
      this.saveToHistory();
    }

    // Apply updates
    updater(this.state);

    // Notify listeners if not in batch mode
    if (this.batchUpdateDepth === 0) {
      this.notifyListeners();
    } else {
      this.pendingNotification = true;
    }
  }

  /**
   * Save current state to history
   */
  private saveToHistory(): void {
    // Remove any future states if we're not at the end
    if (this.historyIndex < this.history.length - 1) {
      this.history = this.history.slice(0, this.historyIndex + 1);
    }

    // Add current state to history
    this.history.push({ ...this.state });

    // Trim history if needed
    if (this.history.length > this.maxHistorySize) {
      this.history.shift();
    } else {
      this.historyIndex++;
    }
  }

  /**
   * Get duration for session type
   */
  private getDurationForSessionType(sessionType: SessionType): number {
    switch (sessionType) {
      case SessionType.WORK:
        return this.state.settings.workDuration;
      case SessionType.SHORT_BREAK:
        return this.state.settings.shortBreakDuration;
      case SessionType.LONG_BREAK:
        return this.state.settings.longBreakDuration;
    }
  }

  /**
   * Get week start date (Monday)
   */
  private getWeekStart(): Date {
    const now = new Date();
    const dayOfWeek = now.getDay();
    const diff = now.getDate() - dayOfWeek + (dayOfWeek === 0 ? -6 : 1);
    return new Date(now.setDate(diff));
  }

  /**
   * Get week statistics
   */
  private getWeekStats(weekStart: Date): {
    workSessions: number;
    totalWorkTime: number;
    completedTasks: number;
    averageDailySessions: number;
  } {
    const weekEnd = new Date(weekStart);
    weekEnd.setDate(weekEnd.getDate() + 7);

    let workSessions = 0;
    let totalWorkTime = 0;
    let completedTasks = 0;

    // Aggregate from daily stats
    for (const [dateStr, stats] of this.state.dailyStats) {
      const date = new Date(dateStr);
      if (date >= weekStart && date < weekEnd) {
        workSessions += stats.workSessions;
        totalWorkTime += stats.totalWorkTime;
      }
    }

    // Count completed tasks in this week
    for (const task of this.state.tasks) {
      if (task.status === TaskStatus.COMPLETED) {
        const completedDate = new Date(task.updatedAt);
        if (completedDate >= weekStart && completedDate < weekEnd) {
          completedTasks++;
        }
      }
    }

    const daysInWeek = 7;
    const averageDailySessions = workSessions / daysInWeek;

    return {
      workSessions,
      totalWorkTime,
      completedTasks,
      averageDailySessions,
    };
  }

  /**
   * Get overall statistics
   */
  private getOverallStats(): {
    totalWorkSessions: number;
    totalWorkTime: number;
    totalCompletedTasks: number;
    longestStreak: number;
  } {
    let totalWorkSessions = 0;
    let totalWorkTime = 0;
    let longestStreak = 0;

    for (const stats of this.state.dailyStats.values()) {
      totalWorkSessions += stats.workSessions;
      totalWorkTime += stats.totalWorkTime;
      longestStreak = Math.max(longestStreak, stats.longestStreak);
    }

    const totalCompletedTasks = this.state.tasks.filter(
      (t) => t.status === TaskStatus.COMPLETED
    ).length;

    return {
      totalWorkSessions,
      totalWorkTime,
      totalCompletedTasks,
      longestStreak,
    };
  }

  /**
   * Calculate focus percentage (completed vs estimated pomodoros)
   */
  private calculateFocusPercentage(): number {
    const today = new Date().toDateString();
    const todaysTasks = this.state.tasks.filter(
      (t) => new Date(t.updatedAt).toDateString() === today
    );

    let totalEstimated = 0;
    let totalCompleted = 0;

    for (const task of todaysTasks) {
      totalEstimated += task.estimatedPomodoros || 1;
      totalCompleted += task.completedPomodoros;
    }

    return totalEstimated > 0
      ? Math.round((totalCompleted / totalEstimated) * 100)
      : 0;
  }

  /**
   * Create empty daily stats
   */
  private createEmptyDailyStats(date: string): DailyStats {
    return {
      date,
      workSessions: 0,
      totalWorkTime: 0,
      totalBreakTime: 0,
      completedTasks: 0,
      longestStreak: 0,
    };
  }

  /**
   * Generate unique ID
   */
  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
  }
}

/**
 * Create a singleton store instance
 */
export let store: AppStore;

/**
 * Initialize the store
 */
export function initStore(initialState?: Partial<AppState>): AppStore {
  if (!store) {
    store = new AppStore(initialState);
  }
  return store;
}

/**
 * Get the store instance (throws if not initialized)
 */
export function getStore(): AppStore {
  if (!store) {
    throw new Error('Store not initialized. Call initStore() first.');
  }
  return store;
}

