// Mock Audio class
class MockAudio {
  src: string;
  volume: number;
  preload: string;
  paused: boolean = true;
  currentTime: number = 0;
  loop: boolean = false;

  private canPlayThroughCallbacks: Array<() => void> = [];
  private errorCallbacks: Array<() => void> = [];
  private playPromise: Promise<void> | null = null;
  private shouldFail: boolean = false;

  constructor(src: string) {
    this.src = src;
    this.volume = 0.7;
    this.preload = 'auto';
  }

  addEventListener(
    event: string,
    callback: () => void,
    options?: { once: boolean }
  ): void {
    if (event === 'canplaythrough') {
      this.canPlayThroughCallbacks.push(callback);
      // Simulate audio loaded
      setTimeout(() => {
        if (!options?.once || this.canPlayThroughCallbacks.includes(callback)) {
          callback();
        }
      }, 0);
    }
    if (event === 'error') {
      this.errorCallbacks.push(callback);
    }
  }

  removeEventListener(event: string, callback: () => void): void {
    if (event === 'canplaythrough') {
      this.canPlayThroughCallbacks = this.canPlayThroughCallbacks.filter(
        (cb) => cb !== callback
      );
    }
    if (event === 'error') {
      this.errorCallbacks = this.errorCallbacks.filter((cb) => cb !== callback);
    }
  }

  async play(): Promise<void> {
    this.paused = false;
    if (this.shouldFail) {
      throw new Error('Playback failed');
    }
    return Promise.resolve();
  }

  pause(): void {
    this.paused = true;
  }

  load(): void {
    // Simulate load
  }

  set shouldFailPlayback(value: boolean) {
    this.shouldFail = value;
  }
}

